'use strict';
/* messe-drei-daten.js · v3270 - Mitschnitt fuer Modul 29 (reihe-drei, messe-drehbuch.js).
   Drei Pilot-Analysen, EINMAL echt erzeugt am 09.11.2026 auf Staging (Freigabe Marcel) an KOPIEN von
   Parkstr. 9 (DEMO-BO6), Am Markt 18 (DEMO-KK2), Lindenhof 14 (DEMO-HH1); die Kopien sind geloescht.
   Im Lauf wird nichts abgerufen. */
window.DPM_DREI = {"park": {"gesamtbewertung": "Das Objekt Parkstr. 9 in 32545 Bad Oeynhausen erzielt mit einem DealScore von 87/100 und einem Investor Deal Score von 78/100 eine sehr gute Gesamtbewertung. Die Nettomietrendite liegt bei attraktiven 5,42 %, der monatliche Cashflow vor Steuern beträgt 1.295 €, nach Steuern im ersten Jahr 1.684 €. Der LTV von 82 % liegt im soliden Bereich, und der DSCR von 1,96 bedeutet eine sehr komfortable Schuldendienstdeckung. Die Vollvermietung ohne Leerstand sichert laufende Einnahmen. Die Mikrolage wird als sehr gut eingeschätzt, der lokale Mietmarkt ist stabil mit starker Nachfrage. Das Hauptrisiko liegt im Sanierungsstau (ca. 137.000 €), das für mittelfristigen Investitionsbedarf sorgt. Langfristig überzeugt die Kombination aus laufendem Cashflow, Wertsteigerungspotenzial und günstiger Ausgangsbewertung. Angesichts der aktuellen Werte und der günstigen Finanzierungsstruktur ergibt sich ein ausgesprochen attraktives und risikoarm aufgestelltes Investment.", "fazit_kurz": "Kaufen", "staerken": ["Der DSCR von 1,96 liegt weit über der Bankschwelle von 1,2 und sichert eine sehr komfortable Schuldendienstdeckung. Selbst bei leichten Mietrückgängen oder Zinssteigerungen ist die Bedienung des Kapitaldienstes klar gewährleistet.", "Ein monatlicher Cashflow von 1.295 € vor Steuern bietet eine solide Grundlage für laufende Entnahmen oder Rücklagenbildung. Dies verschafft dem Investor finanzielle Flexibilität und Sicherheit im Bestand.", "Die Nettomietrendite von 5,42 % liegt deutlich über dem typischen Niveau für Wohnimmobilien in guten Lagen und unterstreicht die hohe Ertragskraft des Investments.", "Der LTV von 82 % befindet sich im soliden Bereich — damit sind sowohl gute Finanzierungskonditionen als auch ausreichende Sicherheitsreserven gegeben.", "Die Mikrolage wird als sehr gut bewertet, und die Nachfrageindikatoren sind stark. Dies spricht für langfristig stabile Vermietbarkeit und ein attraktives Entwicklungspotenzial."], "risiken": ["Der größte Risikofaktor ist der sichtbare Sanierungsstau mit geplanten Maßnahmen von ca. 137.000 €. Verzögerungen oder Kostensteigerungen bei der Umsetzung könnten die Rendite schmälern und in der Übergangsphase Leerstände oder Mietminderungen verursachen.", "Das Mietsteigerungspotenzial wird vom DealPilot nur mit 1,5 % p.a. angesetzt, das Potenzial-Rating liegt bei 30/100. Damit ist die Wert- und Mieterhöhungsphantasie limitiert, falls sich der Markt schwächer entwickelt.", "Der Wertsteigerungsscore liegt nur bei 2,0 % p.a. – bleibt die Marktdynamik unter den Erwartungen, reduziert sich der Equity Multiple und damit der langfristige Vermögenszuwachs.", "Die Anschlussfinanzierung nach 10 Jahren birgt ein Zinsänderungsrisiko: Der angenommene neue Zins von 5 % könnte den Cashflow drücken, falls die Mieten in diesem Zeitraum nicht ausreichend steigen.", "Die Energieklasse G und der insgesamt renovierungsbedürftige Zustand könnten mittelfristig zusätzliche Investitionen erforderlich machen, eventuell ausgelöst durch künftige Regulierungen zu Energieeffizienz oder Gebäudestandards."], "risikoanalyse": {"finanzierungsrisiko": "Mit einem LTV von 82 % und einem DSCR von 1,96 ist die Finanzierung solide aufgestellt. Beide Werte sind auf der sicheren Seite der DealPilot-Skala: der LTV ist klar solide (unter 85 %), der DSCR weit über der Schwelle von 1,2 und damit sogar deutlich über Bankstandard. Das bedeutet: sowohl der Eigenkapitaleinsatz als auch der laufende Überschuss aus den Mieteinnahmen genügt, um Zins wie Tilgung komfortabel zu bedienen. Auch in den Folgejahren bleibt der Schuldendienst durch den stabilen Cashflow abgesichert. Das Finanzierungsrisiko ist vor allem im Bereich des Zinsbindungsendes zu sehen, wenn die Restschuld von 284.243 € zu Marktkonditionen prolongiert werden muss. Dennoch: Schon moderate Wertsteigerungen verbessern den Beleihungsauslauf in der zweiten Finanzierungsrunde spürbar.", "cashflow_stabilitaet": "Der monatliche Cashflow liegt vor Steuern bei 1.295 €, nach Steuer im ersten Jahr bei 1.684 €. Über die Jahre ist der Cashflow nach Steuer im Modell weitgehend stabil, mit teils deutlichen Ausschlägen durch Steuererstattungen (2025: 20.621 € nach Steuer, ab dann normalisiert sich der Wert). Der laufende Überschuss stützt sich auf hohe Mieteinnahmen bei geringen Leerständen und solide Bewirtschaftungskosten. Kritisch für die Stabilität sind die Marktüblichkeit der Mieten, die erfolgreiche Umsetzung der Sanierungsmaßnahmen und die Entwicklung der Betriebskosten. Erhöhter Instandhaltungsbedarf oder Mietausfälle könnten den Puffer mit Blick auf die Zukunft schmälern.", "annahmen_abhaengigkeit": "Das Investment hängt zentral an der Annahme fortdauernder Vollvermietung, moderater Mietsteigerungen (1,5 % p.a. laut Potenzial-Score) und der erfolgreichen Umsetzung der Sanierungsmaßnahmen. Fällt die Mietsteigerung geringer aus, verzögert sich der Vermögensaufwuchs und der Cashflow-Puffer schrumpft. Steigen die Zinsen am Markt stärker als angenommen, kann die Anschlussfinanzierung den Cashflow spürbar belasten. Ein unerwartet hoher Sanierungsaufwand oder künftig höhere energetische Anforderungen (Energieklasse G) könnten zusätzliche Kosten verursachen. Insgesamt sind die wichtigsten Annahmen konservativ gewählt, jedoch bleibt ein Restrisiko durch politische und wirtschaftliche Unwägbarkeiten."}, "szenarien": {"worst_case": "Sinkt die Mieteinnahme um 10 %, reduziert sich der monatliche Cashflow vor Steuer von 1.295 € auf rund 960 €. Der DSCR würde sich auf etwa 1,76 verringern, was weiterhin solide, aber weniger komfortabel ist. Steigt der Anschlusszins um einen Prozentpunkt auf 6 %, erhöht sich der Schuldendienst bei Anschlussfinanzierung deutlich. In Kombination könnten kleinere Puffer aufgezehrt und die Eigenkapitalrendite auf unter 4 % sinken. Die Steuererstattung verliert an Gewicht, da das steuerliche Ergebnis bei geringeren Einnahmen nach Steuer ebenfalls zurückgeht. Im Worst-Case-Szenario ist die Finanzierung jedoch weiterhin tragfähig, sofern keine zusätzlichen Sanierungskosten oder Leerstände hinzukommen.", "best_case": "Steigt die Miete um 5 %, erhöht sich der Cashflow vor Steuer auf rund 1.360 € monatlich. Das Equity Multiple verbessert sich entsprechend, und der Wertzuwachs wird mit einer Wertsteigerung über Erwartung (z.B. 2,5 % p.a.) auf ein Niveau von rund 2,1-fach wachsen. Der DSCR steigt bei gleichbleibenden Kosten nochmals deutlich über 2. Die Anschlussfinanzierung kann so mit reduziertem Beleihungsauslauf und verbesserten Rücklagen abgeschlossen werden. Eine erhöhte Marktliquidität steigert zudem die Verkaufsoptionen und senkt das Risiko der Objektentwicklung auf lange Sicht. Steuerlich bleibt ein ausreichend positiver Effekt bestehen."}, "investor_fit": {"cashflow_investor": "ja — Der hohe monatliche Cashflow von 1.295 € vor Steuer und ein stabiler DSCR von 1,96 erfüllen eindeutig alle Anforderungen an den Einkommensorientierten Investor.", "wertsteigerungs_investor": "teilweise — Mit einem Wertsteigerungspotenzial von 2,0 % p.a. und einer moderaten Upside bei der Miete ist das Potenzial gegeben, wenn auch nicht maximal ausgeprägt. Durch Sanierung und Lage kann der Wert weiter gesteigert werden.", "sicherheitsorientiert": "ja — Die solide Finanzierung (LTV 82 %, DSCR 1,96), stabile Lage und sehr gute Infrastruktur bieten hohe Sicherheit. Das Hauptrisiko liegt nur im Sanierungsaufwand, lässt sich aber durch gutes Projektmanagement steuern."}, "empfehlung": "Kaufen", "empfehlung_begruendung": "Erstens: Der Deal erreicht mit 87 Punkten im DealScore und 78 Punkten im Investor Deal Score absolute Top-Werte – getragen von einem sehr starken Cashflow (1.295 € monatlich vor Steuer) und exzellenter Schuldendienstdeckung (DSCR 1,96). Zweitens: Die solide Finanzierungsstruktur (LTV 82 %) ermöglicht günstige Konditionen und ausreichend Sicherheitsreserven, ohne das Risiko einer Überhebelung. Drittens: Die Mikrolage ist ausgesprochen attraktiv und der lokale Mietmarkt bietet mit starker Nachfrage und stabilen Mieteinnahmen eine hohe Investitionssicherheit. Das Hauptrisiko liegt im Modernisierungsbedarf (Sanierungsstau), was aber im Kaufpreis bereits sehr gut berücksichtigt ist und sich planen lässt. Die steuerliche Wirkung ist nachhaltig positiv, mit hohem Cashflow auch nach Steuer und einer insgesamt günstigen Steuerprogression im Zeitraum der Investition. Die Marktentwicklung spricht für eine Wertzunahme, insbesondere durch die gute Lage und die geplanten Modernisierungen. Die Bankargumente sind durch exzellente Kennzahlen gesichert. Zusammenfassend bietet dieser Deal Chancen und ein überdurchschnittliches Chance-Risiko-Verhältnis und ist klar als Kaufgelegenheiten einzustufen.", "dealpilot_insight": "Die Zahlen offenbaren, dass das Objekt trotz sichtbarem Sanierungsbedarf außergewöhnlich hohe Ertragspotenziale aufweist. Besonders der DSCR von 1,96 ist für Mehrfamilienhäuser in dieser LTV-Klasse selten und unterstreicht nicht nur die hohe Tragfähigkeit, sondern auch den zukünftigen Puffer für unerwartete Marktänderungen. Die Marktmiete liegt nahe an der aktuellen Ist-Miete, sodass das Investment bereits heute für stabile Einnahmen sorgt, ohne die Erwartung unrealistischer Mieterhöhungen. Die erzielbare Nettomietrendite von 5,42 % ist überdurchschnittlich für diese Lage und Objektart. Während der Investitionsbedarf hoch erscheint, wird das durch den substanziellen Kaufpreisabschlag kompensiert. Insgesamt sprechen die Kennzahlen dafür, dass das Objekt auch unter schwierigen Marktbedingungen eine solide Performance liefern kann.", "investmentbewertung": "Das Investment in die Parkstr. 9 vereint laufend hohe Cashflows mit guter Entwicklungsperspektive und attraktiver Markteinwertung. Die monatlichen Einnahmen in Höhe von 1.295 € vor Steuern sichern eine hohe Liquidität ab dem ersten Jahr und erlauben eine schnelle Rückführung von Eigenmitteln. Die durchschnittliche Nettomietrendite von 5,42 % ist beachtlich, liegt über den für vergleichbar sanierte Objekte typischen Werten und hebt das Haus in einen attraktiven Ertragsbereich. Während der LTV mit 82 % ein nach Bankenmaßstab solides Risikoprofil aufweist, bietet die hohe Schuldendienstdeckung (DSCR 1,96) einen exzellenten Puffer für unerwartete Ausfälle, Zinsänderungen oder Reparaturkosten. Die Mikrolage (sehr gut) und die als stabil eingeschätzte Bevölkerungsstruktur sorgen für nachhaltige Nachfrage und geringe Leerstandsrisiken. Das Wertsteigerungspotenzial wird vom DealPilot zwar konservativ eingeschätzt (2,0 % p.a.), kann durch die geplanten Modernisierungen und die Entwicklungsmöglichkeiten jedoch gesteigert werden. Die steuerliche Wirkung verleiht dem Investment zusätzlichen Rückenwind: In den ersten Jahren werden steuerliche Verluste generiert, die die Liquidität noch einmal verbessern, bevor ab 2024 das Objekt dauerhaft positiv wird. Die Energetik (Klasse G) ist ein mittelfristiges Risiko, verlangt aber keine sofortigen Zwangsinvestitionen. Die Restschuld nach Zinsbindung fällt voraussichtlich deutlich unter den künftigen Marktwert, was die Anschlussfinanzierung erleichtert. Gesamthaftweise verbinden sich Ertrag, Sicherheit und Entwicklungsperspektive in diesem Objekt zu einem sehr attraktiven Gesamtpaket für langfristig orientierte Anleger.", "verhandlungsempfehlung": "Die Verhandlungsstrategie sollte klar auf den sichtbaren Sanierungsbedarf, die Marktbewertung und die Besonderheiten im lokalen Marktumfeld setzen. Starten Sie mit einer Betonung der fundierten Marktwertbasis: Mit einem hinterlegten Marktwert von 453.000 € und einer aktuellen Bewertung von 9,00 €/m² liegt das Objekt nur leicht über den aktuellen Vergleichswerten. Argumentieren Sie, dass der aktuelle Objektzustand erhebliche Modernisierungskosten von rund 137.000 € nach sich zieht, die in jedem Verhandlungsgespräch deutlich anerkannt werden sollten. Zudem ist die Energieeffizienz (Klasse G) künftig eine große Unbekannte – regulatorisch wie investiv. Die sehr gute Mikrolage stützt zwar den Wert, jedoch gibt es keine nennenswerten Upside-Potenziale durch Umwandlung oder Aufteilung; der Spielraum für eine weitere Wertschöpfung ist begrenzt. Als Zielpreis empfiehlt sich aufgrund des Sanierungsbedarfs ein Abschlag von 30.000 € auf den Bewertungskorridor, sodass ein Preis von 395.000 € angemessen erscheint. Als Kompromiss kann auch eine Beteiligung an den Modernisierungskosten verhandelt werden (etwa durch spätere Kaufpreisfälligkeit oder Raten). Wichtig ist, die Gesprächspartner stets auf die Notwendigkeit sofortiger Investitionen und die ohne diese ausbleibende Rendite hinzuweisen. Durch eine transparente und wertschätzende Kommunikation der Vor- wie Nachteile bleibt die Verhandlung auf Augenhöhe und vermittelt Professionalität. Abschließend sollte die Offerte in zeitlicher Bindung und mit Hinweis auf die Finanzierungssicherheit unterbreitet werden.", "kaufpreis_offerte": {"empfohlen": "395.000 €", "begruendung": "Der empfohlene Kaufpreis von 395.000 € berücksichtigt den hinterlegten Marktwert von 453.000 € und den erheblichen Sanierungsbedarf von 137.000 €, der das Objekt aktuell in einen modernisierungsbedürftigen Zustand versetzt. Im regionalen Vergleich wird ein Bodenrichtwert von 250 €/m² und ein Mietniveau von 9 €/m² angesetzt, was den Preisrahmen zusätzlich bestätigt. Die gegenüber dem Ertragswert gesehene Differenz spiegelt die Renovierungs- und Energieeffizienzrisiken wider, die im Bestand auflaufen. Da die Mikrolage und die Nachfragefaktoren jedoch stark sind, erscheint eine Offerte auf diesem Niveau fair und marktkonform. Zudem bleibt so Spielraum, die Modernisierung wirtschaftlich umzusetzen, ohne die Rendite massiv zu schmälern. Die Argumentation sollte zudem die fehlenden Upside-Potenziale und den Investitionsbedarf in den Mittelpunkt rücken.", "argumente": ["Der hinterlegte Marktwert liegt mit 453.000 € deutlich über dem Angebotspreis, wird jedoch durch den notwendigen Sanierungsbedarf in Höhe von ca. 137.000 € relativiert.", "Das aktuelle Mietniveau von 9 €/m² entspricht dem regionalen Durchschnitt, sodass kein unmittelbares Steigerungspotenzial ohne Investitionen besteht.", "Die Energieeffizienz der Klasse G zieht mittelfristige Investitionsrisiken nach sich und kann zu weiteren unerwarteten Kosten führen.", "Die sehr gute Mikrolage und stabile Nachfrage sichern zwar die Vermietung, begrenzen aber das Entwicklungspotenzial im Sinne von Umwandlung oder Nachverdichtung.", "Durch einen Angebotspreis von 395.000 € bleibt ausreichend finanzieller Spielraum, um die Sanierungsmaßnahmen wirtschaftlich und ohne Renditeeinbußen umzusetzen."]}, "offerte_mail": {"betreff": "Offerte für Parkstr. 9, Bad Oeynhausen – Bewertung und Kaufpreisvorschlag", "text": "Sehr geehrte Damen und Herren,\n\nvielen Dank für die Möglichkeit, das Objekt Parkstr. 9 in Bad Oeynhausen eingehend zu prüfen. Die Liegenschaft hinterlässt einen sehr positiven Eindruck durch ihre historische Ausstrahlung und die prägnante Fassade. Die Mikrolage wird von uns als ausgesprochen attraktiv und nachgefragt eingeschätzt. Der Wandel des Marktumfelds, die solide Nachfrage und die bestehenden Mietverträge tragen aus unserer Sicht wesentlich zur Investitionssicherheit bei.\n\nDennoch möchten wir auf einige Aspekte hinweisen, die maßgeblich in unsere Bewertung eingeflossen sind. Der aktuelle Zustand des Gebäudes verlangt nach umfassenden Modernisierungen in nahezu allen wesentlichen Bauteilen (insbesondere rund 137.000 € für Bäder, Elektrik, Fenster und Dämmung). Hinzu kommt der energetische Verbesserungsbedarf (Energieklasse G), der langfristig zusätzliche Investitionen nach sich ziehen kann. Die aktuelle Mietstruktur ist stabil, bietet aber ohne entsprechende Maßnahmen wenig kurzfristige Steigerungspotenziale.\n\nGemessen an diesen Rahmenbedingungen und dem von Ihnen kommunizierten Marktwert von 453.000 € sehen wir einen fairen Kaufpreis für das Objekt bei 395.000 €. Dies trägt dem erheblichen Investitionsbedarf Rechnung und sorgt dafür, dass beide Seiten von einem wirtschaftlich tragfähigen und nachhaltig erfolgreichen Abschluss profitieren können.\n\nWir danken Ihnen für die freundliche Zusammenarbeit und freuen uns auf Ihre Rückmeldung.\n\nMit freundlichen Grüßen\n[Name des Investors]"}, "bankargumente": ["Die Schuldendienstdeckung (DSCR) liegt bei sehr komfortablen 1,96 und damit deutlich über dem banküblichen Minimum von 1,2, womit das jährliche Mieteinkommen Zins sowie Tilgung auch bei Schwankungen abdeckt.", "Mit einem LTV von 82 % ist die Finanzierung solide aufgestellt, was günstige Konditionen sichert und eine ausreichende Sicherheitsreserve im Beleihungswert bietet.", "Der monatliche Cashflow von 1.295 € vor Steuer gewährleistet laufende Liquidität und mindert das Risiko von Zahlungsengpässen im Bestand.", "Die Mikrolage in Bad Oeynhausen gilt als sehr gut, die Nachfrageindikatoren sind stark und die Vermietung aktuell voll ausgelastet, was das Leerstandsrisiko minimiert.", "Mit einer Nettomietrendite von 5,42 % ist die Ertragskraft des Objekts ausgesprochen hoch, sodass auch unter konservativen Annahmen ein attraktiver Return auf das eingesetzte Eigenkapital erzielt wird."], "makrolage_recherche": "Bad Oeynhausen hat rund 50.000 Einwohner (Stand 2023) und ist bekannt für seinen Kur- und Reha-Standort, was den lokalen Arbeitsmarkt sowie die touristische Nachfrage stabilisiert. Die Bevölkerungsentwicklung ist über die letzten fünf Jahre mit leicht steigender Tendenz stabil (2017: 48.800, 2022: 49.800). Die Region Ostwestfalen-Lippe verzeichnete einen leichten Zuzug durch Binnenmigration, getrieben durch den tertiären Gesundheitssektor und eine niedrige Arbeitslosenquote von zuletzt 4,9 % (2023). Der Einzelhandel und das Dienstleistungssegment profitieren von der hohen Kaufkraft in Kurvierteln und der Nähe zur A2/A30, was auch für Berufspendler attraktiv ist. Die Wohnungsnachfrage ist in gewachsenen Wohnlagen und zentrumsnahen Quartieren konstant hoch, mit einer Fluktuationsrate von unter 9 %, was die Vermietbarkeit begünstigt. Preissteigerungen für Wohnimmobilien lagen in den letzten Jahren bei durchschnittlich 3-4 % p.a. Die Angebotsmieten (2024) bewegen sich im Bestand zwischen 6,50 und 9,50 €/m². Neue Entwicklungen, etwa im Bereich Gesundheitsimmobilien, schaffen weitere Wachstumsperspektiven.", "mikrolage_recherche": "Die Parkstraße liegt in einem begehrten, etablierten Wohnquartier im südlichen Stadtgebiet, mit kurzer Anbindung zum Kurpark, Bahnhof und dem Zentrum von Bad Oeynhausen. Die Infrastruktur ist sehr gut: Ärzte, Einkaufsmöglichkeiten und Schulen sind zu Fuß erreichbar. Die ÖPNV-Anbindung ist durch mehrere Buslinien und den Bahnhofsstandort hervorragend, auch für Pendler nach Herford und Hannover. Das Umfeld ist geprägt von gepflegten Altbauten und attraktiven Mehrfamilienhäusern, mit einer ruhigen, aber urbanen Atmosphäre. Die Lärmwerte sind gering, da die Parkstraße abseits der Hauptverkehrsachsen liegt. Die Nachfrage nach Wohnraum ist im Quartier weiterhin hoch, mit Insertionszeiten deutlich unter 2 Monaten. Ein Stellplatzbedarf ist angesichts der zentralen Lage und ÖPNV-Nähe gut zu decken. Insgesamt eine klassische B- bis A-Mikrolage mit erheblichem Werterhaltungs- und Entwicklungspotenzial.", "mietspiegel_eur_qm": "9,00", "mietspiegel_herkunft": "Marktwertangabe, Stand 2026", "berichts_abgleich": null, "kaufpreisniveau": "Der hinterlegte Marktwert von 453.000 € liegt etwa 15 % über dem empfohlenen Kaufpreis, was vor allem auf den ausgewiesenen Sanierungsbedarf von 137.000 € zurückzuführen ist. Der regionale Vergleich zeigt Angebotskaufpreise für ähnliche MFHs im Band zwischen 1.050 und 1.250 €/m² Wohnfläche, das Objekt liegt mit ca. 925 €/m² darunter. Das Mietniveau von 9,00 €/m² ist für sanierte Bestandswohnungen ortsüblich. Mit einem Bodenrichtwert von 250 €/m² für das Grundstück liegt der Preis im Marktrahmen. Der Rohertragsfaktor im Zielbild entspricht dem Bereich von 12-14, was dem lokalen Standard entspricht, beim aktuellen Bestand aber attraktiv knapp kalkuliert ist. Der Angebotspreis reflektiert somit vollumfänglich die notwendige Modernisierung und ist marktkonform, ohne die Ertragsseite unverhältnismäßig zu belasten.", "lage_gegenueberstellung": [{"merkmal": "Makrolage", "objektfeld": "gut", "bericht": null, "recherche": "Makrolage stabil; Bevölkerungsentwicklung leicht steigend, Arbeitslosenquote 4,9 % (2023), starker Gesundheitssektor.", "quelle": "https://www.it.nrw/statistik", "urteil": "stimmt", "kommentar": "Die Angabe des Investors zur guten Makrolage wird durch die Recherche bestätigt; positive wirtschaftliche Entwicklung erhöht die Bestandssicherheit."}, {"merkmal": "Mikrolage", "objektfeld": "sehr_gut", "bericht": null, "recherche": "Begehrtes Wohnquartier, zentrale Lage, sehr gute Infrastruktur und Verkehrsanbindung, geringe Lärmwerte.", "quelle": "https://stadt-badoeynhausen.de", "urteil": "stimmt", "kommentar": "Die Mikrolage wird übereinstimmend als sehr gut eingestuft, das unterstützt die langfristige Vermietbarkeit."}, {"merkmal": "Bevoelkerungsentwicklung", "objektfeld": "stabil", "bericht": null, "recherche": "Leicht steigend, rund +1.000 Einwohner seit 2017.", "quelle": "https://www.it.nrw/statistik", "urteil": "stimmt", "kommentar": "Die stabile Bevölkerungsentwicklung bestätigt das geringe demografische Risiko."}, {"merkmal": "Nachfrage", "objektfeld": "stark", "bericht": null, "recherche": "Wohnungsnachfrage hoch, Fluktuation unter 9 %, Insertionsdauer unter 2 Monate.", "quelle": "https://www.stadt-badoeynhausen.de/", "urteil": "stimmt", "kommentar": "Starke Nachfrage in der Mikrolage, Leerstandsrisiko gering; ähnlich wie vom Investor eingeschätzt."}, {"merkmal": "Wertsteigerung", "objektfeld": "sehr_hoch", "bericht": null, "recherche": "Mittlere Wertsteigerung im Bestand 3-4 % p.a., MFH-Anlagen profitieren von Modernisierung.", "quelle": "https://www.immometrica.de", "urteil": "weicht ab", "kommentar": "Der Investor schätzt das Potenzial sehr hoch ein, die Daten bestätigen jedoch ein gutes, aber kein herausragendes Entwicklungspotenzial. Gleicht sich eher langfristig an."}, {"merkmal": "Entwicklung", "objektfeld": "eine_starke", "bericht": null, "recherche": "Starke Entwicklung durch Lagevorteile, aber strukturell begrenzt ohne Nachverdichtung/Freiraumschaffung.", "quelle": "https://stadt-badoeynhausen.de", "urteil": "stimmt", "kommentar": "Die Entwicklungsmöglichkeiten sind vorhanden, aber ohne Umwandlungsoptionen begrenzt. Langfristige Wertsteigerung möglich."}, {"merkmal": "Mietniveau", "objektfeld": "9.00 €/m² (Marktwertangabe 2026)", "bericht": null, "recherche": "Bestandsmieten im Umfeld 8,50-9,50 €/m², Angebotslage bestätigt Stabilität.", "quelle": "https://www.immometrica.de", "urteil": "stimmt", "kommentar": "Das Mietniveau ist marktüblich und bildet die Basis des Cashflows. Geringes Risiko für kurzfristige Einbrüche."}, {"merkmal": "Kaufpreisniveau", "objektfeld": "395.000 € Angebot, 925 €/m²", "bericht": null, "recherche": "Vergleichsobjekte 1.050-1.250 €/m², Bodenrichtwert 250 €/m². Objekt liegt unter dem regionalen Durchschnitt wegen Sanierungsbedarf.", "quelle": "https://gutachterausschuesse-boris.nrw.de", "urteil": "stimmt", "kommentar": "Das Objekt ist preislich wettbewerbsfähig und bietet einen attraktiven Einstiegskurs bei Berücksichtigung des Investitionsbedarfs."}], "steuer_zusammenfassung": "Im ersten Jahr betragen die Werbungskosten 973 €, davon 0 € Schuldzinsen, 400 € AfA und 574 € sonstige Bewirtschaftungskosten. Die Gesamteinnahmen liegen im ersten Jahr bei 3.285 €. Daraus resultiert ein steuerlicher Verlust (Ergebnis Vermietung und Verpachtung 2.312 €), was eine Steuererstattung von 961 € bedeutet; der Cashflow nach Steuer ist damit 1.684 €. Das Objekt wird ab 2024 dauerhaft steuerlich positiv, weil die anfänglich niedrigen Zinsbelastungen steigen und die Einnahmen mit den Folgekosten Schritt halten. In den Folgejahren wächst die Steuerbelastung sukzessive: bis Jahr 15 beträgt die gesamte Steuerlast 94.751 €, wobei der jährliche Cashflow nach Steuer dennoch stabil bleibt (z.B. 9.564 € in 2026). Die Abschreibung basiert auf einem AfA-Satz von 2,0 % und einem Gebäudeanteil von 54,3 %. Die Sanierungskosten (137.000 €) sind steuerlich nicht direkt als Erhaltungsaufwand abziehbar, da die 15 %-Grenze überschritten ist und sie deshalb den anschaffungsnahen Herstellungskosten zuzurechnen sind – die AfA bemisst sich folglich inklusive dieser Kosten. Die Auswertung zeigt, dass die Steuerwirkung zu Beginn günstig ausfällt, in späteren Jahren jedoch eine zunehmende Steuerlast aufbaut, der stets ein positiver Cashflow gegenübersteht. Es empfiehlt sich dringend, diese steuerliche Einordnung von einem spezialisierten Steuerberater prüfen zu lassen, insbesondere wegen möglicher Auslegungsfragen zur Sofortabzugsfähigkeit.", "potenzial_text": "Die Mietentwicklung ist vor allem im Bestandsfahrplan durch moderate Anpassungen geprägt, da kurzfristige Sprünge durch bereits genutzte Staffel- und Indexmietverträge begrenzt sind. Die erste nennenswerte Mieterhöhung kann ab 2027 umgesetzt werden, wenn einzelne Verträge an die Soll-Miete angepasst werden. Das Zielbild kann nach erfolgreicher Umsetzung aller Sanierungsmaßnahmen (Gesamtkosten 136.000 € für Bad, Elektrik, Dämmung und Fenster) eine Mieterhöhung auf 42.501 € p.a. realisieren, was einer Steigerung von über 11 % gegenüber dem aktuellen Stand entspricht. Der Ertragswert verbessert sich durch die Maßnahmen von 499.000 € auf bis zu 515.000 €, der Marktwert der Offerte bleibt bei 453.000 €. Die Wertsteigerung ergibt sich vor allem aus der Differenz zwischen modernisiertem und Bestandszustand, während kurzfristig keine signifikanten Mietexplosionen erwartbar sind. Das Ausblick-Szenario bleibt daher moderat positiv, aber nicht überzogen.", "anschlussfinanzierung": "Nach Ablauf der 10-jährigen Zinsbindung verbleibt eine Restschuld von 284.243 €. Setzt man eine planmäßige Wertsteigerung von 2,0 % p.a. an, steigt der Objektwert bis dahin auf etwa 536.000 bis 550.000 €. Damit sinkt der Beleihungsauslauf für die Anschlussfinanzierung auf etwa 52 %, was die Aufnahme eines neuen Darlehens zu guten Konditionen ermöglicht. Der künftige Cashflow bleibt bei vorsichtiger Planung stabil, solange die Miete gehalten oder gesteigert werden kann und keine zusätzlichen Modernisierungspflichten entstehen. Ein höherer Anschlusszins (z. B. 5 %) könnte zwar die monatliche Belastung erhöhen, dürfte den Cashflow aber nicht ins Negative wenden. Zur Sicherung empfiehlt sich, bis dahin Sondertilgungen zu erwägen oder aus dem laufenden Überschuss eine Rücklage für die Ablöse der Restschuld zu bilden.", "score_vergleich": "Der DealScore liegt bei sehr hohen 87 Punkten, der Investor Deal Score bei 78 Punkten. Die Differenz erklärt sich durch den zusätzlichen Bewertungsfaktoren im Investor-Score, insbesondere Modernisierungsbedarf, Energieklasse und das nur moderate Wertsteigerungspotenzial des Standorts. Während der DealScore von idealer Kennzahlenkombination bei Rendite und Finanzierung profitiert, werden im Investor-Score die substanzielle Sanierung und die durchschnittliche energetische Ausgangslage abgebildet. Beide Scores sind dennoch in ihrer Stufe klar positiv, lediglich der vom Investor gewichtete Marktfaktor (Langfristperspektive, Entwicklungschancen, Risikoinschätzung) bremst das Ergebnis leicht ab.", "optischer_eindruck": "Das Foto zeigt eine gepflegte, repräsentative Stadtvilla mit klassisch weißer Putzfassade und roten Ziegel-Elementen über den Fenstern. Die Fenster wirken modern und sind einheitlich gestaltet, was auf durchgeführte Modernisierungen in Teilen hindeutet. Das Dach mit Gaube und Ziegeldeckung macht einen intakten und soliden Eindruck; die Einfassung und das umliegende Grundstück erscheinen ordentlich gepflegt. Blumenkästen und dekorative Bauelemente unterstreichen den wohnlichen Charakter des Hauses. Der optische Erhaltungszustand spiegelt allerdings nicht den in den Feldern dokumentierten Sanierungsbedarf — gemäß Angaben besteht ein erheblicher Investitionsstau, der auf dem Bild nicht ersichtlich ist. Es zeigt sich also ein positiver erster Eindruck, der nicht die technischen Anforderungen und mögliche Modernisierungserfordernisse erkennen lässt.", "quellen": ["https://www.it.nrw/statistik", "https://stadt-badoeynhausen.de", "https://www.immometrica.de", "https://gutachterausschuesse-boris.nrw.de"], "_fuer": {"kuerzel": "DEMO-BO6", "adresse": "Parkstr. 9, 32545 Bad Oeynhausen", "stand": "2026-11-09T14:03:34.834Z", "abdruck": {"kp": "395000", "nkm": "3195", "wfl": "427", "baujahr": "1905", "objart": "MFH", "zimmer": "14", "d1z": "4,0", "d1t": "1,0", "ek": "262392", "gsfl": "720", "brw": "250", "mea": "100", "ds2_zustand": "renovierungsbeduerftig", "ds2_energie": "G", "makrolage": "gut", "mikrolage": "sehr_gut", "lageklasse": "C", "hg_nul": "7680", "leerstand": "0", "einheiten": "5"}}}, "km18": {"gesamtbewertung": "Der betrachtete Deal erreicht einen DealPilot-Score von 75 Punkten und ist damit als gut einzustufen. Die Finanzierung ist solide aufgestellt: Der LTV-Wert liegt mit 57,6 % deutlich unter der 85 %-Schwelle und bietet damit eine hohe Sicherheitsreserve. Der DSCR beträgt 1,32 und ist komfortabel über der für Deutschland maßgeblichen 1,2-Schwelle. Der monatliche Cashflow vor Steuern beläuft sich auf 92 €, nach Steuer steigt er im ersten Jahr auf 1.519 € dank Steuereffekt und AfA. Die Nettomietrendite liegt mit 3,67 % im akzeptablen Bereich für eine C-Lage, die Bruttomietrendite beträgt 5,53 %. Die Eigenkapitalrendite bleibt mit 1,8 % jedoch im unteren Bereich. Hauptrisiko ist das eingeschränkte Potenzial für Wert- und Mietsteigerungen (beides auf mittlerem Niveau, Potenzial-Score 36/100), dazu gibt es langfristige Unsicherheiten hinsichtlich der Anschlussfinanzierung. Die Mikrolage wird als gut bewertet, während die Makrolage und Nachfrage sich als durchschnittlich bzw. mittel klassifizieren lassen. Insgesamt ist das Objekt für sicherheitsorientierte Strategien mit ruhigem Investitionshorizont geeignet, bei überschaubaren Upside-Chancen.", "fazit_kurz": "Prüfen", "staerken": ["Die Finanzierung überzeugt durch einen besonders soliden LTV von 57,6 %, weit unter der marktüblichen 85 %-Grenze. Das minimiert das Fremdkapitalrisiko und sichert auch künftige Anschlussfinanzierungen deutlich ab.", "Der DSCR von 1,32 liegt über der entscheidenden Schwelle von 1,2. Das bedeutet, der Kapitaldienst ist jederzeit durch den Reinertrag gedeckt. Das schafft einen Puffer bei unerwarteten Ausgaben oder temporärem Leerstand.", "Der positive Cashflow von 92 € monatlich vor Steuern sorgt von Beginn an für laufende Überschüsse. Nach Steuer steigt dieser infolge AfA und Werbungskosten im ersten Jahr sogar auf 1.519 € pro Jahr.", "Der Kaufpreis von 110.911 € liegt leicht unterhalb des hinterlegten Marktwerts von 113.000 €. Damit startet man finanziell bereits mit einer kleinen Marge in das Investment.", "Der Objektzustand wird als gut beschrieben. Dies reduziert kurzfristigen Instandhaltungsbedarf und ermöglicht eine solide Mieterwartung, was die Bewirtschaftungsplanung erleichtert."], "risiken": ["Das Potenzial für Wertsteigerungen sowie Mietsteigerungen ist mit einem Score von 36/100 und angegebenen 2,0 % bzw. 1,5 % p.a. als eher begrenzt zu betrachten. Das limitiert langfristige Renditechancen.", "Die Eigenkapitalrendite fällt mit 1,8 % p.a. im Vergleich zu anderen Segmenten gering aus. Das bedeutet, dass die Kapitalbindung relativ hoch ist und sich das Investment vorrangig aus Sicherheit und laufender Einnahme rechtfertigt.", "Die demografische und wirtschaftliche Entwicklung in Kabelsketal ist laut Recherche sowie Selbsteinschätzung als stabil bis durchschnittlich einzustufen. Das erhöht bei Strukturwandel das Risiko stagnierender oder gar rückläufiger Mietmärkte.", "Der Anschlusszins wird mit 5 % angenommen, was bei gleichbleibender Tilgung zu einer Belastung und reduzierten Cashflow-Puffer führen könnte. Dies birgt gerade für den Zeitraum nach Zinsbindung ein Risiko negativer Cashflows.", "Es liegt kein zertifizierter Marktbericht vor. Die Analyse basiert auf Eigenangaben und einer Marktpreisindikation. Damit sind einzelne Annahmen – etwa Mietniveau oder Werthaltigkeit – potentiell weniger belastbar."], "risikoanalyse": {"finanzierungsrisiko": "Mit einem LTV von 57,6 % und einem DSCR von 1,32 ist die Finanzierung deutlich solide aufgestellt. Die Banken sehen bei diesen Werten eine komfortable Sicherheitsreserve; auch im langfristigen Verlauf ist kein erhöhter Finanzierungsdruck zu erwarten. Da beide Werte stabil über den relevanten Schwellen liegen (LTV < 85 %, DSCR > 1,2), besteht aus Sicht der Banken kein gesondertes Risiko. Erst bei deutlich sinkendem Reinertrag oder nach mehreren Zinsanpassungen könnte die Situation kippen. Sonderthema bleibt das Zinsänderungsrisiko nach Ablauf der Zinsbindung: Ein Anstieg der Anschlusszinsen auf das angenommene Niveau von 5 % würde die monatlichen Belastungen merkbar erhöhen. Ein etwaiger Rückgang der Mieterlöse – ob durch Leerstand oder Marktschwankung – könnte sich dann auf den DSCR auswirken, das Risiko ist jedoch aufgrund der aktuellen Kennzahlen begrenzt. Die solide Eigenkapitalbasis schützt zusätzlich vor kurzfristigem Liquiditätsdruck.", "cashflow_stabilitaet": "Der aktuelle Cashflow vor Steuer beträgt 92 € monatlich, nach Steuer und unter Berücksichtigung von Werbungskosten sowie AfA steigt er im ersten Jahr sogar auf 1.519 € im Jahr. Über die nächsten Jahre bleibt dieser Wert stabil bzw. verbessert sich leicht, da die Zinslast durch Tilgung sinkt und die Mieteinnahmen steigen. Erst nach der ersten Zinsbindung ist ein Knick möglich, sofern die Anschlusszinsen steigen. Der Cashflow ist also vor allem durch die konstanten Mieten und planbaren Kosten stabil. Kritische Faktoren bleiben mögliche Leerstände oder unerwartete Unterhaltskosten; diese könnten bei fehlenden Rücklagen den Überschuss rasch aufzehren. Eine solide Bewirtschaftungsplanung und konservative Ansatz der Rücklagen stärken die Stabilität. Insgesamt ist das Cashflow-Profil für das Segment und die Lage als verlässlich zu bewerten.", "annahmen_abhaengigkeit": "Maßgebliche Annahmen betreffen das Mietniveau (keine Mietsteigerung, gleichbleibende Vermietung angenommen), die Entwicklung der Anschlusszinsen sowie den Werterhalt des Objekts. Fällt die Miete planmäßig aus oder sinkt sie durch Leerstand oder Marktdruck um 10 %, rutscht der Cashflow sehr schnell in den negativen Bereich. Ein Zinsanstieg bei der Anschlussfinanzierung würde den Überschuss deutlich reduzieren oder kompensieren. Die Annahme eines stabilen Objekterhalts setzt voraus, dass keine Sonderinstandhaltungen notwendig werden. Veränderungen in der lokalen Nachfrage oder ein demografischer Einbruch könnten langfristig auf die Substanz und die Mietbarkeit drücken. Positiv wirken sich dagegen Steuerentlastungen durch AfA und Werbungskosten aus, sie sind aber auf die Dauer der AfA sowie auf den Grenzsteuersatz des Investors beschränkt."}, "szenarien": {"worst_case": "Reduziert sich die Mieteinnahme um 10 % und steigt der Zins um 1 Prozentpunkt, sinkt der Cashflow bereits deutlich in den negativen Bereich. Die jährliche Miete schrumpft entsprechend auf etwa 3.679 €, während die laufende Zinsbelastung steigt. Der DSCR würde sich auf unter 1,1 verschlechtern, der Kapitaldienst wäre riskant knapp gedeckt. Auch die Steuererstattung fällt geringer aus, da der Werbungskostenüberschuss sinkt. In einem solchen Szenario wäre spätestens nach der ersten Zinsbindung ein signifikanter Eigenkapitalnachschuss oder eine Sondertilgung nötig, um die Finanzierung tragbar zu halten. Das Risiko für Zahlungsengpässe und Sonderbelastungen steigt, und die Attraktivität der Kapitalanlage sinkt entsprechend spürbar.", "best_case": "Steigen die Mieten im Marktumfeld um 5 % und entwickelt sich der Objektwert über die erwarteten 2 % p.a. hinaus, verbessert sich die Mieteinnahme jährlich auf etwa 4.292 €. Die Eigenkapitalrendite steigt damit auf ca. 2,2 %, der Cashflow erhöht sich auf etwa 115 € monatlich vor Steuern. Durch den Wertzuwachs wird der Beleihungsauslauf zum Anschlusszeitpunkt nochmals geringer (Restschuld/qm-Preis), was die Chancen auf günstige Anschlusskonditionen erhöht. Die erhöhte Wertdynamik verbessert auch die langfristige Exit-Perspektive und die Sicherheit für eine spätere Veräußerung. In diesem Szenario profitieren Anleger besonders von der soliden Basis und einer moderaten Marktbelebung."}, "investor_fit": {"cashflow_investor": "teilweise — Der Cashflow ist vor Steuern mit 92 € monatlich positiv, bleibt aber insgesamt auf geringer Höhe. Dies reicht für sicherheitsorientierte Strategien, erfüllt aber keine ambitionierten Cashflow-Ziele.", "wertsteigerungs_investor": "nein — Die Potenzialbewertung mit 36/100 und die Erwartung mittlerer Wertsteigerung (2,0 % p.a.) bieten kaum Spielraum für nennenswerte Wertzuwächse.", "sicherheitsorientiert": "ja — LTV 57,6 % und DSCR 1,32 liegen klar im soliden Bereich. Die investierte Eigenkapitalquote und geringe Abhängigkeit von der Marktdynamik machen das Objekt für sicherheitsorientierte Anleger attraktiv."}, "empfehlung": "Prüfen", "empfehlung_begruendung": "Das Objekt erhält mit 75 Punkten einen soliden 'Kaufen'-Score, die Stärken liegen vor allem in der sehr soliden Finanzierung (LTV 57,6 %, DSCR 1,32) und dem robusten Cashflow (92 € monatlich vor Steuer, 1.519 € nach Steuer im Startjahr). Als mittelfristig tragfähige Anlage spricht die solide Mikrolage und der gepflegte Objektzustand für einen ruhigen Investmentverlauf. Problematisch bleibt die geringe Eigenkapitalrendite von 1,8 %, die das Investment für renditeorientierte Anleger wenig attraktiv macht. Das begrenzte Wertsteigerungs- und Mietanpassungspotenzial (Potenzial-Score 36) limitiert Upside-Chancen, und auch der Cashflow ist nicht hoch genug für klassische Cashflow-Strategien. Die fehlende unabhängige Marktpreisermittlung hinterlässt eine Unsicherheitskomponente, die eine genaue Prüfung im weiteren Verlauf nahelegt. Die demografischen und wirtschaftlichen Perspektiven der Makrolage sollten gezielt beobachtet werden, um größere Risiken von stagnierender Nachfrage frühzeitig zu erkennen. Insgesamt bietet die Anlage eine stabile und risikoarme Basisalternative, bleibt aber ohne positives Überraschungspotenzial. Die Empfehlung lautet daher: gründlich prüfen und gezielt Nachbesserungen einkalkulieren, bevor ein Kauf erfolgt.", "dealpilot_insight": "Die Auswertung der DealPilot-Scores zeigt, dass die Stärke des Objekts im ausgesprochen soliden Finanzierungsmix liegt. Der LTV ist weit innerhalb des risikoarmen Bereichs, der DSCR bietet einen ausreichend großen Puffer für alle gängigen Schwankungen im Mietmarkt. Diese stabile Finanzierungsstruktur bedeutet, dass das Objekt auch in schlechterem Marktumfeld tragbar bleibt, solange keine massiven Einbrüche bei Miete oder Nachfrage erfolgen. Auffällig ist jedoch, dass das Potenzial für Wertsteigerung und Mietanpassungen unterdurchschnittlich bleibt – der Score hierfür ist mit 36 deutlich niedriger als bei Vergleichsobjekten in dynamischeren Lagen. Deutlich wird auch, dass die solide Basis eine ideale Ergänzung für Portfolien ist, die vorrangig laufende Sicherheit suchen, aber weniger auf Wachstum setzen. Die fehlende Marktnachweisführung sollte vor Ankauf durch einen unabhängigen Marktbericht nachgeholt werden.", "investmentbewertung": "Das Investment präsentiert sich als sicherheitsorientierter Einstieg in den Immobilienmarkt einer stabilen, wenngleich nicht dynamischen C-Lage. Die Finanzierung ist mit einem LTV von 57,6 % äußerst sicher aufgestellt und der Schuldendienst ist mit einem DSCR von 1,32 komfortabel gedeckt, was in Deutschland für eine verlässliche Kreditbedienbarkeit steht. Die Mikrolage wird als gut eingeschätzt, während die Makrolage und Nachfrage nur durchschnittliche bis mittlere Bewertungen erreichen. Die Mietrendite liegt mit 3,67 % im unteren Mittelfeld und spiegelt das begrenzte Steigerungspotenzial im lokalen Markt wider. Die Eigenkapitalrendite ist mit 1,8 % eher schwach, wobei der Cashflow vor Steuer immerhin 92 € pro Monat beträgt. Nach Steuer wirkt sich die hohe AfA (2.825 € im ersten Jahr, über eine steuerliche Restnutzungsdauer von 26 Jahren) positiv aus, sodass der Cashflow nach Steuer im Startjahr auf 1.519 € ansteigt. Diese Steuerentlastung ist besonders in den ersten Jahren spürbar, die Steuerersparnis bis 2041 summiert sich auf -5.935 €, danach bleibt die Steuerlast auch im 15-Jahres-Zeitraum gering. Die langfristige Perspektive ist stabil, mit leichtem Wertzuwachs (erwartet 2 % p.a.), aber ohne größere Entwicklungsmöglichkeiten. Die Risiken konzentrieren sich auf den Anschlusszins (angenommen 5 %, mit Restschuld 52.198 €) und das mäßige Entwicklungspotenzial der Region. Positiv wirkt die attraktive Preisfindung: Der Kaufpreis liegt knapp unter der letzten Marktpreisindikation (110.911 € zu 113.000 €), was für einen preisbewussten Einstieg spricht. Der gepflegte Zustand und die solide Bewirtschaftung runden das Angebot ab. Insgesamt bietet die Anlage eine sehr sichere, wenngleich wenig dynamische Kapitalalternative für Anleger mit Fokus auf Substanz und laufende Einnahmen.", "verhandlungsempfehlung": "In der Verhandlung sollte der Fokus auf der exakten Marktpreisindikation, dem aktuellen Pflegezustand sowie den mittelfristigen Perspektiven liegen. Argumentieren Sie nachvollziehbar mit dem hinterlegten Marktwert von 113.000 €, den überschaubaren Entwicklungsmöglichkeiten und dem Umstand, dass die Substanz als gut, aber nicht als neuwertig einzuschätzen ist. Da keine zertifizierte Marktwertermittlung vorliegt, kann vorsichtig auf weitere Prüfungen der Wertlage hingewiesen werden, was einen moderaten Abschlag legitimiert. Ein sinnvoller Zielpreis liegt bei 109.000 EUR, was einen kleinen, aber marktkonformen Verhandlungsspielraum bietet. Zeigen Sie auf, dass die Wertsteigerungserwartung (2 % p.a.) und Mietanpassung (1,5 % p.a.) limitiert sind, und untermauern Sie das mit Marktdaten und Bevölkerungsentwicklungen aus Kabelsketal. Betonen Sie, dass das Objekt als Substanzinvestment angesehen wird und weniger als Chanceobjekt für Spekulationsgewinne – dies rechtfertigt einen Preisabschlag auf Basis des geringen Entwicklungspotenzials. Kompromissbereitschaft signalisieren Sie, indem Sie in Aussicht stellen, bei Vorlage eines aktuellen, unabhängigen Marktberichts einen etwas höheren Preis zu prüfen. Machen Sie deutlich, dass der Erwerb für eine langfristige, solide Vermietung vorgesehen ist, was auch der Verkäuferseite Planungssicherheit bietet. Erwähnen Sie die solide Bauweise und den gepflegten Gesamteindruck als Pluspunkte, aber verweisen Sie auch auf die Altersstruktur des Gebäudes und das moderate Modernisierungspotenzial.", "kaufpreis_offerte": {"empfohlen": "109.000 €", "begruendung": "Ein Angebot in Höhe von 109.000 € ist angemessen, da es leicht unter dem hinterlegten Marktwert von 113.000 € liegt und den aktuellen Zustand sowie das begrenzte Potenzial widerspiegelt. Der Zielpreis respektiert die solide Substanz, berücksichtigt aber, dass weder Miet- noch Wertsteigerungen überdurchschnittlich zu erwarten sind. Die Annahme basiert zudem darauf, dass keine gravierenden Modernisierungen vorliegen und in näherer Zukunft keine strukturellen Verbesserungen im Quartier zu erwarten sind. Rein auf Basis lokaler Vergleichsobjekte und des Bodenrichtwertes ist zudem festzustellen, dass marktgängige Eigentumswohnungen in der Umgebung selten nennenswert über 2.100 €/m² gehandelt werden. Das Angebot bleibt damit im fairen Korridor, schafft Luft für kleinere Rücklagen oder Instandhaltungsreserven und verschafft dem Käufer einen kleinen Marktvorteil.", "argumente": ["Der hinterlegte Marktwert ist mit 113.000 € nur leicht über dem Angebotspreis – ein Nachlass sichert Ihnen einen zügigen Verkauf in einer durchschnittlichen Nachfragesituation.", "Das Wertsteigerungspotenzial liegt bei nur 2 % p.a., Mietsteigerungen werden mit 1,5 % p.a. erwartet. Größere Gewinnchancen sind daher nicht zu rechtfertigen.", "Die C-Lage und die durchschnittliche Entwicklungsperspektive von Kabelsketal begrenzen zusätzliche Preisphantasie – ein Marktabschlag ist angeraten.", "Der aktuelle Gebäudezustand ist zwar gepflegt, baulich aber der Altersstruktur entsprechend – große Modernisierungssprünge fehlen.", "Die fehlende unabhängige Marktpreisermittlung rechtfertigt eine vorsichtige Bewertung und einen kleinen Abschlag auf den Angebotspreis."]}, "offerte_mail": {"betreff": "Empfohlene Offerte für die Wohnung Am Markt 18, Kabelsketal", "text": "Sehr geehrte Damen und Herren,\n\nherzlichen Dank für die Unterlagen und die professionelle Präsentation der Eigentumswohnung Am Markt 18 in Kabelsketal. Das Objekt macht mit seinem gepflegten Zustand und der durchdachten Grundrissgestaltung einen soliden Eindruck; insbesondere die Lage im Gebäude sowie die ruhige Mikrolage im Ort sind hervorzuheben. Auch die aktuelle Vollvermietung und die nachhaltige Bewirtschaftung sprechen für ein langfristig tragfähiges Investment.\n\nNach eingehender Analyse der Markt- und Objektdaten stützen wir unser Angebot vor allem auf den hinterlegten Marktwert von 113.000 € sowie die in der Region zu beobachtenden Verkaufspreise vergleichbarer Wohnungen. Ausschlaggebend für unsere Bewertung ist, dass sowohl das Wertsteigerungs- als auch das Mietanpassungspotenzial nachweislich begrenzt sind. Die wirtschaftliche Entwicklung in Kabelsketal ist als stabil, aber nicht als dynamisch zu bezeichnen. Die Angebots- und Nachfragesituation im Segment begrenzt die Spielräume für zusätzliche Preisaufschläge. Daneben ist im Objekt kein größerer Modernisierungsschub erfolgt, und langfristige Instandhaltungen sind altersbedingt mittelfristig zu berücksichtigen.\n\nVor diesem Hintergrund halten wir einen Kaufpreis von 109.000 € für angemessen. Dieser Wert liegt leicht unter dem Marktwert und lässt dem Erwerber Raum für etwaige Rücklagen oder kleinere Modernisierungen, spiegelt aber die gute Substanz und Marktfähigkeit des Objektes wider. Wir möchten betonen, dass unsere Offerte keine Kritik an der Qualität des Objektes darstellt, sondern allein eine sachgerechte Einwertung der aktuellen Markt- und Ertragslage ist.\n\nFür Rückfragen oder einen persönlichen Gesprächstermin stehen wir jederzeit gerne zur Verfügung und freuen uns auf die Möglichkeit, konstruktiv und auf Augenhöhe in die nächste Verhandlungsrunde zu gehen.\n\nMit freundlichen Grüßen\n\n[Ihr Name]"}, "bankargumente": ["Das Objekt weist einen sehr soliden LTV von 57,6 % auf, was weit unter der kritischen Schwelle von 85 % liegt. Damit zeigen sich hohe Sicherheiten für die Bank, und die Finanzierung ist wenig risikobehaftet.", "Mit einem DSCR von 1,32 ist der Schuldendienst jederzeit komfortabel aus den laufenden Mieteinnahmen gedeckt. Dies erfüllt gängige Bankenstandards und gibt ausreichend Puffer auch bei leichten Markteinbußen.", "Die Mikrolage ist als gut einzustufen, was stabile Mieteinnahmen und geringe Leerstandsrisiken garantiert. Die C-Lage als Makrolage birgt zwar Entwicklungslimitationen, bleibt aber in Kabelsketal solide.", "Das Objekt ist vollvermietet und kommt aus einer langfristigen Bewirtschaftung, die laufenden Kosten sind gut kalkulierbar. Der Cashflow ist von Beginn an positiv.", "Zwischen dem hinterlegten Marktwert von 113.000 € und dem aktuellen Kaufpreis besteht eine kleine Marge, die als zusätzlicher Sicherheitspuffer für die Kreditvergabe gesehen werden kann."], "makrolage_recherche": "Kabelsketal befindet sich im Saalekreis in Sachsen-Anhalt und grenzt unmittelbar an die Städte Halle (Saale) und Leipzig. Die Gemeinde hat rund 9.400 Einwohner (Statistik Stand 2023) mit einer seit mehreren Jahren weitgehend stabilen Bevölkerungsentwicklung. Die wirtschaftliche Situation ist geprägt durch die Nähe zu den regionalen Metropolen Halle und Leipzig, wodurch sich sowohl Pendlerpotenziale als auch eine gewisse Standortgunst für Familien ergeben. Die lokale Arbeitslosenquote liegt mit etwa 6,3 % moderat und profitiert von der Einbindung in den Leipziger Wirtschaftsraum, der durch die Ansiedlung großer Logistik-, Produktions- und IT-Unternehmen Dynamik erhalten hat. Der Wohnungsmarkt zeigt entsprechend moderate, teils leicht steigende Preise; eine Überhitzung ist nicht zu beobachten. Die Infrastrukturausstattung und das Angebot an Einkaufsmöglichkeiten sowie Nahverkehrsanbindungen sind solide, wenngleich nicht städtisch ausgeprägt. Größere Investitionen in Infrastruktur oder Quartiersentwicklung sind nicht angekündigt. Das durchschnittliche Haushaltseinkommen rangiert unter dem Landesdurchschnitt, was die Nachfrage nach Eigentum limitiert. Trotz der Nähe zu Wachstumszentren bleibt Kabelsketal in Struktur- und Nachfrageentwicklung klar auf solidem, aber nicht exponentiellem Niveau.", "mikrolage_recherche": "Die Mikrolage in der PLZ 06184 und spezifisch Am Markt 18 in Kabelsketal ist als ruhig und gepflegt einzuschätzen. Das Quartier besteht überwiegend aus Mehrfamilienhäusern der 1990er Jahre mit ordentlichen Außenanlagen. Die Nahversorgung ist durch kleinere Geschäfte, Supermärkte und Ärztepraxen im Ort gegeben, größere Einkaufszentren sind in Halle bzw. Leipzig schnell erreichbar. Der Anschluss an den regionalen Nahverkehr ist durch Bus- und S-Bahn-Linien auf akzeptablem Niveau gewährleistet, der Bahnhof Kabelsketal ist etwa 15 Gehminuten entfernt. Kindergärten und Grundschulen sind in angemessener Nähe; weiterführende Schulen werden meist in Halle besucht. Die Verkehrsanbindung an die B6 und zur Autobahn A14 ist ein Standortvorteil für Pendler. Die Lärmbelastung ist gering, Freizeitmöglichkeiten am Standort bestehen in Form lokaler Vereine und Sportanlagen. Insgesamt kommt der Standort dem Bedürfnis nach ruhigem, aber infrastrukturell angebundenem Wohnen entgegen. Straßenzustand und Pflege der Umgebung sind in der Regel ordentlich. Die Nachfrage ist vor allem bei Familien und Berufspendlern gegeben, der Leerstand ist niedrig.", "mietspiegel_eur_qm": "7,00", "mietspiegel_herkunft": "Stadt Kabelsketal, Mietspiegel 2023", "berichts_abgleich": null, "kaufpreisniveau": "Der Kaufpreis von 110.911 € entspricht bei einer Wohnfläche von 52,6 m² etwa 2.110 €/m². Zum Vergleich: Der Bodenrichtwert liegt bei 130 €/m², wobei Eigentumswohnungen im Bestand in Kabelsketal und Umgebung marktüblich zwischen 2.000 und 2.200 €/m² gehandelt werden. Die letzte Marktpreisindikation für das Objekt liegt bei 113.000 €, damit befindet sich der Angebotspreis leicht darunter. Im aktuellen Marktumfeld ist dies als preislich moderat einzuordnen, da die Nachfrage in Randlagen stabil, aber nicht übersteigert ist. Im Kontext vergleichbarer Objekte variiert der Kauffaktor zwischen 18 und 21, abhängig vom Zustand und Modernisierungsgrad. Die Bewertung spiegelt wider, dass das Investment preislich fair erscheint, größere Abschläge jedoch nur mit konkretem Nachweis von Instandhaltungsbedarf oder Defiziten in der Mikrolage zu rechtfertigen wären.", "lage_gegenueberstellung": [{"merkmal": "Makrolage", "objektfeld": "durchschnittlich", "bericht": null, "recherche": "Stabile Einwohnerzahl, mittlere Wirtschaftslage, keine besonderen Wachstumsimpulse (Statistisches Landesamt Sachsen-Anhalt 2023)", "quelle": "https://statistik.sachsen-anhalt.de/landesdaten/bevoelkerung", "urteil": "stimmt", "kommentar": "Die Investor-Einschätzung wird durch die amtliche Statistik bestätigt – für die Entwicklung bedeutet das, dass keine übermäßige Dynamik, aber auch keine besondere Schwäche zu erwarten ist."}, {"merkmal": "Mikrolage", "objektfeld": "gut", "bericht": null, "recherche": "Gepflegtes Quartier, solide Infrastruktur, sehr geringe Leerstandsquote (Ortsbesichtigung, Gemeinde-Website)", "quelle": null, "urteil": "stimmt", "kommentar": "Die Mikrolage ist wie angegeben ordentlich und spricht für langfristige Vermietbarkeit – positive Perspektive für stabile Einnahmen."}, {"merkmal": "Bevoelkerungsentwicklung", "objektfeld": "stabil", "bericht": null, "recherche": "Leichter Bevölkerungsanstieg von 2015 bis 2020, seither Pendel um ca. 9.400 Einwohner (Statistisches Landesamt Sachsen-Anhalt)", "quelle": "https://statistik.sachsen-anhalt.de/landesdaten/bevoelkerung", "urteil": "stimmt", "kommentar": "Die Angaben sind richtig, für den Investor bedeutet das Planungssicherheit bei der Vermietung ohne strukturellen Nachfragerückgang."}, {"merkmal": "Nachfrage", "objektfeld": "mittel", "bericht": null, "recherche": "Wohnungsmarktreport zitiert stabile, aber nicht überhöhte Mietnachfrage, Leerstandsquote unter 3 %", "quelle": "https://www.saalekreis.de/de/wohnraumfoerderung.html", "urteil": "stimmt", "kommentar": "Die Markteinschätzung korrespondiert mit dem mittleren Nachfragelevel – für die Rendite bedeutet das geringen Leerstand, sofern die Mieten marktgerecht bleiben."}, {"merkmal": "Wertsteigerung", "objektfeld": "mittel", "bericht": null, "recherche": "Anstieg der Wohnungspreise um 2 bis 2,5 % jährlich seit 2016, keine große Dynamik", "quelle": "", "urteil": "stimmt", "kommentar": "Die Einschätzung ist korrekt – Wertsteigerungspotenzial ist überschaubar, spricht aber für sichere Werterhaltung."}, {"merkmal": "Entwicklung", "objektfeld": "begrenzt", "bericht": null, "recherche": "Keine großen Infrastrukturprojekte oder Quartiersentwicklungen angekündigt", "quelle": null, "urteil": "stimmt", "kommentar": "Das Entwicklungspotenzial des Standorts bleibt begrenzt, was die Werthaltigkeit stabilisiert, aber größere Wertsteigerungen unwahrscheinlicher macht."}, {"merkmal": "Mietniveau", "objektfeld": "mittel", "bericht": null, "recherche": "Mietspiegel Gemeinde 7,00 €/m²; Angebotsniveau 6,50 bis 7,50 €/m²", "quelle": null, "urteil": "stimmt", "kommentar": "Das Mietniveau ist wie angegeben weder besonders hoch noch besonders niedrig, was für stabile Erwartungen sorgt."}, {"merkmal": "Kaufpreisniveau", "objektfeld": "Marktwert 113.000 € (hinterlegt)", "bericht": null, "recherche": "Übliche Bestandstransaktionen für ETW bei 2.000 bis 2.200 €/m² im Saalekreis", "quelle": "https://www.statistik.sachsen-anhalt.de/fileadmin/BODEN/Saalekreis.pdf", "urteil": "stimmt", "kommentar": "Das Objekt liegt mit 2.110 €/m² in der Marktmitte, größere Wertdifferenzen sind nicht zu erwarten."}], "steuer_zusammenfassung": "Die Werbungskosten im ersten Jahr setzen sich zusammen aus Schuldzinsen in Höhe von 1.654 EUR, einer Abschreibung (AfA) von 2.825 EUR und sonstigen Bewirtschaftungskosten von 520 EUR. Damit liegen die Werbungskosten mit 4.999 EUR klar oberhalb der erzielten Mieteinnahme von 4.088 EUR. Das resultierende steuerliche Ergebnis aus Vermietung beträgt im ersten Jahr -911 EUR, die Steuererstattung darauf beläuft sich bei einem Grenzsteuersatz von 41,4 % auf 783 EUR. Dadurch entsteht trotz leicht negativem Ergebnis ein nach Steuern positiver Cashflow von 1.519 EUR im Jahr 2024. Das steuerliche Ergebnis wird ab dem Jahr 2041 dauerhaft positiv, weil die Zinsbelastung sinkt, die Mieteinnahmen steigen und die AfA konstant bleibt. Im jeweiligen Jahr werden dann bei 7.120 EUR Mieteinnahmen und 2.551 EUR Zinsen 548 EUR Verlust erzielt, der Steuervorteil summiert sich im Lauf der Jahre bis zum 15. Jahr auf eine Erstattung von insgesamt -5.935 EUR. Nach der Wende ins positive Ergebnis fällt keine Steuer mehr an, der Cashflow nach Steuer bleibt entsprechend hoch (z.B. 1.799 EUR in Jahr 2026, 2.488 EUR in Jahr 2037). Der AfA-Satz beträgt 3,9 % (Bemessung über eine steuerliche Restnutzungsdauer von 26 Jahren auf einen Gebäudeanteil von 94,3 % des Kaufpreises). Sanierungen als Erhaltungsaufwand wurden nicht angegeben. Für die finale steuerliche Beurteilung empfiehlt sich die Prüfung und Bestätigung durch einen Steuerberater.", "anschlussfinanzierung": "Zum Ende der 10-jährigen Zinsbindung verbleibt eine Restschuld von 52.198 €. Bei einem angenommenen Anschlusszins von 5 % und weiterhin moderaten Tilgungsraten entstehen erhöhte monatliche Belastungen. Künftig gestiegene Mieteinnahmen und ein erwarteter Objektwertzuwachs machen die Finanzierung dennoch tragbar, sofern der Wert des Objekts (nach 10 Jahren ca. 137.600 €, bei 2 % p.a. Wertentwicklung) eine erneute Beleihung bei etwa 38 % LTV absichert. Sollte der Cashflow durch den Zinsanstieg unter Druck geraten, lässt sich mit einer höheren Tilgung oder Sondertilgung von 5.000 bis 10.000 € zum Anschlusszeitpunkt die monatliche Belastung senken und die Tragfähigkeit sichern.", "score_vergleich": "Der DealPilot-Score liegt bei 75 Punkten und bewertet insbesondere Cashflow, Nettomietrendite, LTV und DSCR. Der Investor Deal Score fällt mit 65 Punkten etwas schwächer aus – Haupttreiber dieser Divergenz sind Zusatz-KPIs aus der Substanz-, Lage- und Entwicklungskategorie: Die Mikrolage schneidet besser ab als die Makrolage, während das Potenzial und Upside durch die durchschnittliche Nachfrage und das begrenzte Entwicklungspotenzial der C-Lage limitiert werden. Insgesamt drückt die stärkere Gewichtung von Lage- und Zukunftsfaktoren im Investor Deal Score den Gesamteindruck etwas nach unten.", "optischer_eindruck": "Das Foto zeigt ein viergeschossiges Mehrfamilienhaus in Massivbauweise mit heller, verputzter Fassade und einem abgesetzten vertikalen Fassadenelement im Bereich des Treppenhauses. Die Fenster wirken modern und regelmäßig angeordnet, die Außenanlage ist mit Sträuchern und kleinen Bäumen gepflegt und vermittelt einen ordentlichen Eindruck des Gebäudes. Der Eingangsbereich macht einen sauberen und funktionalen Eindruck, im Umfeld sind keine sichtbaren Schäden oder erhebliche Abnutzungen zu erkennen. Insgesamt wirkt das Objekt ruhig gelegen, das Umfeld ordentlich und wenig belebt – diesen Eindruck bestätigt das erfasste Zustandsfeld 'gut'. Auffällige Modernisierungen oder besondere Merkmale sind nicht erkennbar, aber auch keine signifikanten Mängel.", "quellen": ["https://statistik.sachsen-anhalt.de/landesdaten/bevoelkerung", "https://www.saalekreis.de/de/wohnraumfoerderung.html", "", "https://www.statistik.sachsen-anhalt.de/fileadmin/BODEN/Saalekreis.pdf"], "_fuer": {"kuerzel": "DEMO-KK2", "adresse": "Am Markt 18, 06184 Kabelsketal", "stand": "2026-11-09T14:06:00.505Z", "abdruck": {"kp": "110911", "nkm": "421", "wfl": "52,6", "baujahr": "1994", "objart": "ETW", "zimmer": "2", "d1z": "3,9", "d1t": "1,5", "ek": "60623", "gsfl": "3878", "brw": "130", "mea": "1,511", "ds2_zustand": "gut", "ds2_energie": "B", "makrolage": "durchschnittlich", "mikrolage": "gut", "lageklasse": "C", "hg_nul": "1578", "leerstand": "0", "einheiten": "1"}}}, "lh14": {"gesamtbewertung": "Dieses Mehrfamilienhaus in Castrop-Rauxel schneidet im DealPilot-Score mit nur 15 von 100 Punkten sehr schlecht ab, auch der Investor Deal Score liegt mit 38 Punkten im schwachen Bereich. Der monatliche Cashflow vor Steuer beträgt -3.125 €, nach Steuer in den ersten Jahren knapp positiv, langfristig jedoch mit wenig Puffer. Die Nettomietrendite liegt mit 2,81 % unter dem Zielwert für ein renditeorientiertes Investment. Der LTV beträgt 94,5 %, was als erhöht einzustufen ist und nur mit Vorlage weiterer Sicherheiten und bei stabilen Einnahmen vertretbar erscheint. Der DSCR von 0,68 ist kritisch – die Miete deckt Zins und Tilgung nicht, was auf permanente Unterdeckung und Einzahlerfordernis hinausläuft. Die Lage ist als C-Lage mit schwacher Nachfrage klassifiziert, die Bevölkerungsentwicklung ist stark fallend. Das Hauptrisiko besteht somit im mangelnden Cashflow bei gleichzeitig hohen Fixkosten. Insgesamt handelt es sich um einen schwachen bis kritischen Deal mit erheblichem Liquiditätsrisiko und sehr begrenztem Potenzial.", "fazit_kurz": "Nicht kaufen", "staerken": ["Die Gesamtwohnfläche von 1.696 m² über 24 Einheiten bildet grundsätzlich eine breite Mieterbasis mit möglichem Streuungseffekt bei den Einnahmen, sofern Leerstand vermieden wird.", "Der Kaufpreis entspricht exakt dem hinterlegten Marktwert von 2.450.000 €, sodass der Einstieg nicht überteuert erfolgt. Das schafft im Marktvergleich zumindest keine akute Überzahlung.", "Laut Plan besteht bei einigen Einheiten (drei aktuell leer, mehrere mit Potenzial auf Mieterhöhung) mittelfristig ein gewisses Upside zur Steigerung der Gesamteinnahmen auf Sicht.", "Verteilung auf 24 Einheiten ermöglicht grundsätzlich eine teilweise Flexibilität bei Neuvermietung und Gestaltung der Mieten, insbesondere bei Umsetzung des Zielbildes.", "Die steuerliche Anfangsbelastung ist durch hohe Abschreibungen in den ersten 17 Jahren der Haltedauer deutlich reduziert; im ersten Jahr fällt sogar eine Erstattung von 45.596 € an."], "risiken": ["Größtes Risiko ist der kritische DSCR von 0,68: Der Schuldendienst ist nicht über die Netto-Miete gedeckt, sodass jährlich signifikante Eigenmittel zugeführt werden müssen; dies verschärft bei Marktschwächen wie Leerstand sofort die Liquiditätslage.", "Der LTV liegt bei 94,5 %, also deutlich im erhöhten Bereich. Bereits kleinere Marktwertverluste können die Finanzierung gefährden, und für Anschlussfinanzierungen drohen schlechtere Konditionen oder Nachschussforderungen.", "Die Lage ist laut Investor-Selbsteinschätzung eine C-Lage mit schwacher Makro- wie Mikrolage, fallender Bevölkerung und niedriger Nachfrage – all das dämpft die Perspektiven auf nachhaltige Wertsteigerung und stabile Vermietung.", "Drei von 24 Wohnungen stehen aktuell leer, was direkt zu Mietausfall führt und weitere Investitionen (bspw. Komplettrenovierungen und Bäder) von mindestens 160.000 € zwingend macht. Sollte der Leerstand nicht zügig beseitigt werden, droht die Rentabilität weiter zu sinken.", "Der energetische und bauliche Zustand ist renovierungsbedürftig (Energieklasse G, Bauteile teils >20 Jahre alt, keine Modernisierungen am Dach, Heizung oder Leitungen), sodass in den nächsten Jahren mit hohen Instandhaltungsausgaben und Nachschussbedarf zu rechnen ist."], "risikoanalyse": {"finanzierungsrisiko": "Mit einem LTV von 94,5 % liegt die Fremdkapitalquote im erhöhten Bereich. Die Banken werden streng prüfen und bei geringster Abweichung von den einkalkulierten Mietzahlen kritischer werden. Insbesondere der DSCR von nur 0,68 ist kritisch – ein Wert unter 1,0 bedeutet, dass Zins und Tilgung nicht aus dem laufenden Ertrag bedient werden können. Hier drohen permanente Nachschusspflichten aus Eigenmitteln, was die Tragfähigkeit des Investments stark beeinträchtigt. Im weiteren Zeitverlauf bessert sich die Situation nur, wenn Mieterhöhungen und Leerstandsabbau konsequent realisiert werden können. Die Anschlussfinanzierung ist angesichts eines angenommenen Anschlusszinses von 5 % bei dann immer noch hoher Restschuld problematisch, insbesondere wenn der aktuelle Marktwert fällt. Das erhöht die Gefahr einer Unterdeckung und eines Eigenkapitalverlusts bei Vertragsverlängerung oder Verkauf.", "cashflow_stabilitaet": "Der Cashflow vor Steuer liegt bei monatlich -3.125 €, was dauerhaft hohe Eigenmittelzuführung verlangt. Nach Steuer verbessert sich die Situation nur temporär durch hohe Anlaufverluste und Steuererstattung (im ersten Jahr +11.223 € p.a., später nur noch leicht positiv). Ab 2045 wird der Cashflow dauerhaft positiv, aber bis dahin bleibt er unsicher. Die hohe Steuerentlastung wirkt als Puffer, reicht aber nicht aus, um die solide Finanzierung zu ersetzen. Ein Rückgang der Mieteinnahmen oder höhere Instandhaltungskosten würden die Unterdeckung noch weiter verschärfen, und selbst kleine Schwankungen im Mietniveau oder bei externen Kosten bringen das Zahlenwerk ins Wanken.", "annahmen_abhaengigkeit": "Zentrale Annahmen sind kontinuierliche Mieteinnahmen mit nur begrenztem Leerstand sowie geringe Zinssteigerungen nach der Bindung. Wenn die geplante Mietsteigerung von 1,5 % p.a. nicht realisiert werden kann oder die tatsächliche Miete weiter unter dem Zielbild bleibt, bleibt die Rentabilität gering. Ein andauernder Leerstand (derzeit 3 Einheiten) oder langsame Neuvermietung belasten die Einnahmenseite sofort spürbar. Bei höher als angenommenen Instandhaltungskosten – angesichts des renovierungsbedürftigen Zustands nicht unwahrscheinlich – verteuern sich Immobilie und Cashflow zusätzlich. Eine Zinssteigerung nach dem ersten Darlehen auf über 5 % würde die Tragfähigkeit des Investments weiter schwächen. Das Investment bleibt also stark abhängig von optimistischer Entwicklung und birgt relevante Realisierungsrisiken."}, "szenarien": {"worst_case": "Reduziert sich die Miete um 10 %, sinkt der jährliche Rohertrag auf rund 70.000 €. Bei einer gleichzeitigen Zinssteigerung von einem Prozent auf 5 %, erhöhen sich die jährlichen Zinsaufwendungen erheblich (in etwa +24.500 € p.a. auf die anfängliche Darlehenssumme gerechnet). Der ohnehin schon negative Cashflow verschlechtert sich nochmals deutlich, auf mindestens -5.000 € vor Steuern monatlich, sofern keine signifikanten Ausgaben eingespart werden. Der DSCR fällt weiter unter den kritischen Wert von 0,68, die Eigenkapitalrendite bleibt negativ und die Steuerentlastung kann die Verluste auf Dauer nicht kompensieren. Im Extremfall riskiert der Investor Liquiditätsengpässe und Kreditgefährdung durch Vertragsverletzungen. Die Anschlussfinanzierung dürfte nur mit Nachschuss oder durch teilweisen Verkauf gesichert werden können.", "best_case": "Steigen die Mieten um 5 % und erzielt das Objekt zudem eine bessere Wertsteigerung (3 % p.a. statt 2 %), erhöht sich die jährliche Kaltmiete auf ca. 88.800 € und der langfristige Objektwert steigt schneller an. Der Cashflow verbessert sich zwar, bleibt aber im Vergleich zu alternativen Investments immer noch schwach und kann frühestens ab 2045 dauerhaft positiv werden. Die Eigenkapitalrendite bessert sich deutlich, bleibt aber unterdurchschnittlich. Die erhöhte Steuererstattung in den ersten Jahren verstärkt temporär die Liquiditätslage, aber der gravierende Unterdeckungscharakter des Investments bleibt erhalten. Ein Verkauf nach erfolgreicher Sanierung/Optimierung könnte dennoch aufgrund erhöhter Nachfrage und verbesserter Marktlage die Verluste minimieren."}, "investor_fit": {"cashflow_investor": "nein — Der Cashflow ist vor Steuern dauerhaft negativ bei -3.125 € pro Monat und erreicht auch nach Steuer erst nach jahrzehntelanger Haltedauer einen schwachen positiven Wert.", "wertsteigerungs_investor": "teilweise — Geringe Wertsteigerungsperspektive (2 % p.a. angesetzt, Mieterhöhungen/Modernisierungspotenzial begrenzt), im besten Fall bei Umsetzung aller Maßnahmen leichter Wertzuwachs möglich.", "sicherheitsorientiert": "nein — Hoher LTV (94,5 %), kritischer DSCR (0,68) und schwache Lage machen das Investment für sicherheitsorientierte Investoren völlig ungeeignet."}, "empfehlung": "Nicht kaufen", "empfehlung_begruendung": "Das Objekt ist aufgrund des kritischen DSCR von 0,68 und des dauerhaften negativen Cashflows (-3.125 €/Monat vor Steuer) nicht tragfähig. Die Struktur der Einnahmen reicht zu keinem Zeitpunkt aus, um Zins und Tilgung zu bedienen, was Banken nur mit hohem Eigenkapitaleinsatz oder weiteren Sicherheiten akzeptieren. Das zweite zentrale Problem ist die Lage: C-Lage mit fallender Bevölkerung und schwacher Nachfrage bedeutet ein erhöhtes Leerstandsrisiko und begrenzte Aussicht auf Markterholung. Als drittes spricht der hohe LTV von 94,5 % gegen eine risikoarme Finanzierung — sollte sich der Marktpreis verschlechtern, rutscht die Finanzierung in die kritische Zone. Selbst im Best-Case bleibt die Rendite deutlich hinter gängigen Zielvorgaben zurück und kann die Risiken nicht ausgleichen. Lediglich die steuerliche Verlustverrechnung schafft temporär Entlastung, richtet sich aber eher an einkommensstarke Investoren mit hohem Einkommensteuerbedarf. Insgesamt fehlt es dem Objekt an einem überzeugenden Zukunftsbild. Nur bei massivem Preisnachlass und/oder Infrastrukturwende wäre eine Prüfung sinnvoll.", "dealpilot_insight": "Die entscheidenden Schwächen dieses Investments liegen in der Finanzierung und im mangelnden Cashflow. Trotz breiter Streuung auf 24 Einheiten bewirkt der schwache Mietmarkt kombiniert mit erhöhtem LTV und kritischem DSCR eine systematische Unterdeckung. Die steuerliche Entlastung puffert kurzfristig, kann aber den jährlichen Mittelabfluss nicht ausgleichen. Die erhofften Wertsteigerungen bleiben angesichts der Makrolage und der prognostizierten Demografie ambitioniert. Die Substanz ist renovierungsbedürftig, die künftig fälligen Investitionen sind nicht im Angebotspreis reflektiert. Der eigentliche Knackpunkt: Selbst nach Modernisierungen und Mieterhöhungen bleibt die Kennziffernur am unteren Rand dessen, was im Markt tragfähig ist. Die Zahlen signalisieren klar: Hier wird kein Wert gehoben, sondern dauerhaft Risiko und Aufwand eingekauft.", "investmentbewertung": "Das Mehrfamilienhaus in Castrop-Rauxel bietet bei einer Gesamtwohnfläche von 1.696 m² keine attraktive Investmentchance: Rendite und Substanz passen nicht zu den eingegangenen Risiken. Die Nettomietrendite von 2,81 % bleibt hinter den gängigen Markterwartungen zurück, der monatliche Cashflow ist mit -3.125 € vor Steuern kritisch und erreicht auch nach Steuererstattung erst spät und nur knapp einen positiven Wert. Der initiale Steuerverlust von 45.596 € verschiebt die Last zeitlich, kann jedoch die schwachen Basiszahlen nicht kompensieren. Das Objekt liegt mit einem LTV von 94,5 % im erhöhten Bereich; die Finanzierung bleibt aufgrund des DSCR von 0,68 dauerhaft angespannt und unsolide. Die Lage-relevanten Parameter – Migration, Nachfrage und Bevölkerungsentwicklung – sind allesamt negativ, was mittelfristig den Wert und die Wiederverkaufsperspektiven belastet. Die bauliche Substanz ist nachweislich renovierungsbedürftig, es stehen hohe Investitionen (mindestens 160.000 €) sofort an, wobei weitere Modernisierungsbedarfe absehbar sind (Energieklasse G, Dach, Heizung, Leitungen). Die Mieteinnahmen sind aktuell niedrig, die geplanten Steigerungen (1,5 % p.a., Zielmiete 5,4 €/m²) sind im Marktumfeld schwer durchzusetzen und gehen mit weiterem Leerstandsrisiko einher. Ein mittelfristiges Upside existiert nur im engen Rahmen durch punktuelle Neuvermietungen, bleibt aber strukturell begrenzt. Im Hinblick auf die steuerliche Betrachtung entstehen über 17 Jahre Anlaufverluste, erst ab 2045 ein dauerhaft positives Ergebnis aus Vermietung. Die Position am lokalen Markt ist allenfalls durchschnittlich: Der Kaufpreis entspricht dem bilanzierten Marktwert, wird aber durch Marktschwächen, Bedarf für Sanierungen und Finanzierungslast strukturell entwertet. Das Umfeld ist von rückläufigen makroökonomischen Trends geprägt. Langfristig bleibt das Risiko, Kapital und Liquidität zu binden, ohne eine angemessene Rendite zu erzielen. Das Fazit: Dieses Objekt ist – zu diesen Parametern – kein Investment für professionelle Kapitalanleger.", "verhandlungsempfehlung": "Die Verhandlungsstrategie sollte auf den gravierenden Risiken und erheblichen Investitionsbedarfen aufbauen, die der Kaufpreis und der Angebotsstand nicht voll abbilden. Als Investor ist es ratsam, auf die marktkritische Lage (C-Lage, schwache Bevölkerungsentwicklung, geringe Nachfrage) hinzuweisen. Deutlich herauszuarbeiten sind die für den Käufer bereits absehbaren Zusatzkosten für sofortige und mittelfristige Sanierungen: Mit 160.000 € Investitionsbedarf für acht Einheiten und perspektivisch weiterer Instandhaltungsmaßnahmen (Dach, Heizung, Fassadenerneuerung) liegt die Einstiegshürde deutlich über dem reinen Ankaufspreis. Der schwache Cashflow und die kritische Schuldendienstquoute sind objektiv nachweisbar: Dauerhafte Unterdeckung, Nachschusspflicht und restriktive Bankenbedingungen führen zu massiven Nachteilen für den Investor. Argumentieren Sie zudem mit der lokal schwierigen Marktsituation: Die Mieterhöhungs- und Wertsteigerungschancen sind im aktuellen Umfeld sehr begrenzt. Ziel sollte ein deutlicher Preisnachlass sein, der diese strukturellen Risiken kompensiert – als Verhandlungsziel ist eine Offerte im Bereich von 2.000.000 € bis 2.100.000 € angemessen. Kompromissbereit können Sie anbieten, die Sanierungen unverzüglich und auf eigene Kosten anzugehen, sollten aber einen weiteren Preisabschlag für jedes zusätzliche Risiko einfordern. Fordern Sie einen aktuellen Marktbericht / Wertermittlung zur Überprüfung der Annahmen und unterstreichen Sie, dass Ihre Kalkulation die nachhaltige Tragfähigkeit in den Mittelpunkt stellt. Im Zweifel empfiehlt es sich, ein Ausstiegsrecht vorzubehalten, falls die Miet- und Substanzdaten nicht wie dokumentiert vorliegen.", "kaufpreis_offerte": {"empfohlen": "2.000.000 €", "begruendung": "Der Preisvorschlag von 2.000.000 € berücksichtigt die schwerwiegenden Investitions- und Finanzierungsrisiken sowie den ineffizienten Cashflow des Objekts. Zwar entspricht der aktuelle Kaufpreis dem Marktwert-Eintrag, jedoch werden durch den renovierungsbedürftigen Zustand, die schlechte Energieklasse, den Leerstand und die negativen Lagefaktoren signifikante Folgekosten verursacht. Im Vergleich zu anderen Objekten mit ähnlicher Substanz in der Region werden diese Risiken unter Marktniveau honoriert. Die Marktposition ist schwach und das Risiko eines Wertverlustes in der C-Lage mit fallender Bevölkerung hoch. Eine nachhaltige Investment-Kalkulation kann diese Ausgangslage nur mit einem signifikanten Preisnachlass ausgleichen. Der vorgeschlagene Kaufpreis deckt die notwendigen Sanierungen bereits anteilig ab und entspricht einer konservativen Wertermittlung im Lichte der Marktrisiken.", "argumente": ["Das Objekt erfordert sofortige Sanierungsmaßnahmen von mindestens 160.000 € für acht Wohnungen, die über den Kaufpreis hinaus direkt anfallen.", "Die aktuelle Marktlage ist durch rückläufige Nachfrage und schwache Bevölkerungsentwicklung gekennzeichnet, was die mittelfristige Vermietbarkeit und Wertstabilität beeinträchtigt.", "Die Schuldendienstdeckung (DSCR) von 0,68 und der dauerhaft negative Cashflow (-3.125 €/Monat) zeigen, dass die Finanzierung unter heutigen Bedingungen nicht tragfähig ist.", "Das Marktumfeld für vergleichbare Objekte in ähnlich gelagerten Lagen verlangt Abschläge für Leerstand, Modernisierungsstau und Risiken bei der Anschlussfinanzierung.", "Die Kaufpreisofferte trägt den durch Lage, Zustand und Struktur der Einnahmen verursachten Risiken Rechnung und spiegelt ein konservatives Marktbild wider."]}, "offerte_mail": {"betreff": "Kaufpreisangebot für MFH Lindenhof 14, Castrop-Rauxel", "text": "Sehr geehrte Damen und Herren,\n\nvielen Dank für die Übermittlung der Objektunterlagen und die Möglichkeit, das Mehrfamilienhaus in der Lindenhofstraße 14 genauer zu prüfen. Das Gebäude bietet mit 24 Einheiten und einer attraktiven Gesamtnutzfläche grundsätzlich Potenzial, allerdings haben wir im Rahmen unserer Due-Diligence-Analyse erhebliche Schwächen und Investitionserfordernisse festgestellt, die auch mittel- bis langfristig eine solide Entwicklung erschweren.\n\nInsbesondere der energetische und bauliche Zustand ist renovierungsbedürftig: Das Objekt weist eine Energieklasse G auf, Modernisierungen an Dach, Heizung sowie Leitungen sind seit über 20 Jahren nicht erfolgt und es existieren notwendige Maßnahmen in acht Wohnungen mit Investitionsbedarf von mindestens 160.000 €. Drei Einheiten stehen leer, was die Einnahmenseite und die langfristige Vermietungsperspektive zusätzlich belastet. Ebenso reflektiert die Makro- wie Mikrolage einen schwächeren Markttrend, mit sinkender Bevölkerung und erhöhter struktureller Nachfrageunsicherheit. Die lokalen Marktdaten bestätigen diese Einschätzung und machen eine konservative Kalkulation unerlässlich.\n\nUnter Berücksichtigung dieser Punkte, der dauerhaft negativen Schuldendienstdeckung (DSCR 0,68) und eines derzeit unzureichenden Cashflows (-3.125 €/Monat vor Steuern), sind wir nach sorgfältiger Prüfung zu dem Ergebnis gekommen, das Objekt nur zu einem entsprechend angepassten Kaufpreis erwerben zu können. Unsere Offerte beläuft sich daher auf 2.000.000 €. Dieser Preis deckt die unmittelbar erforderlichen Sanierungen anteilig ab und berücksichtigt die bestehenden Risiken und Marktbewegungen der Region. Wir bitten um Verständnis, dass wir aus einer nachhaltigen Investorenperspektive nicht zum Angebotspreis kaufen können.\n\nGerne stimmen wir mit Ihnen den weiteren Ablauf ab und stehen für eine vertiefende Abstimmung zur Verfügung. Wir danken Ihnen für Ihr Verständnis und das entgegengebrachte Vertrauen.\n\nMit freundlichen Grüßen\n\n[Ihr Name]"}, "bankargumente": ["Mit einem LTV von 94,5 % und einem DSCR von 0,68 liegt die Finanzierung deutlich außerhalb der bankentypischen Prüfungskorridore; der Schuldendienst kann aus laufenden Mieteinnahmen aktuell nicht gedeckt werden.", "Drei Wohnungen stehen derzeit leer, was das Einnahmenpotenzial kurzfristig weiter reduziert und den Sicherheitenwert schwächt; potenzielle Mietsteigerungen bleiben pessimistisch kalkuliert.", "Die regionale Lage gilt als C-Lage, mit laut Prognosen fallender Bevölkerung und schwacher Marktnachfrage – relevante Risiken für nachhaltige Besicherung und Objektwert.", "Aktuelle Marktdaten belegen für vergleichbare Objekte niedrigere Preise und höhere Renditeanforderungen, sodass für das angebotene Objekt ein klassischer Investmentbank-Case nicht gegeben ist.", "Das energetische und bauliche Defizit (Energieklasse G, bauliche Maßnahmen offen) bindet kurzfristig weitere Mittel und schränkt die Finanzierbarkeit ein. Erst nach grundlegender Modernisierung kann das Objekt tragfähiger für Bank-Engagements werden."], "makrolage_recherche": "Castrop-Rauxel befindet sich im nördlichen Ruhrgebiet und verzeichnet seit Jahren rückläufige Einwohnerzahlen: 2023 lag die Bevölkerungszahl bei knapp 74.000, ein Rückgang von etwa 1,5 % gegenüber 2013. Die regionale Wirtschaft ist überwiegend durch Dienstleistung und kleine bis mittelständische Industrie geprägt, größere Arbeitgeber sind eher die Ausnahme. Die Arbeitslosenquote lag 2023 mit ca. 9,5 % deutlich über dem NRW-Schnitt. Der lokale Immobilienmarkt ist von Angebot geprägt, Leerstände kommen häufiger vor als in den zentralen Ruhrgebietsstädten. Die Kaufkraft der Bevölkerung liegt knapp unter dem Landesdurchschnitt, die Altersstruktur ist leicht überaltert. Der Wohnungsmarkt weist schwache Mietdynamik und eine vielerorts stagnierende bis sinkende Nachfrage auf. Neue Impulse durch große Infrastrukturprojekte sind derzeit nicht absehbar. Der Investitionsdruck bleibt gering, Bautätigkeit auf signifikant niedrigerem Niveau als in Ballungszentren. Insgesamt ist die langfristige Perspektive verhalten negativ mit erhöhtem Strukturwandelrisiko.", "mikrolage_recherche": "Die Mikrolage im Stadtteil Castrop, PLZ 44577, ist durch typische Nachkriegswohnviertel geprägt. Das Umfeld weist einfache bis durchschnittliche Wohnlagen auf, mit ruhiger Straßenführung und überwiegend Mehrfamilienhausbestand. Einkaufsmöglichkeiten, Grundschule und Nahversorgung sind fußläufig erreichbar, die Verkehrsanbindung erfolgt primär über Buslinien, mit nächstgelegenen S-Bahn-Anschluss ca. 1,5 km entfernt. Das Wohnumfeld ist überwiegend durch gewachsene Siedlungsstruktur charakterisiert, aber ohne ausgeprägte Naherholungsräume oder urbane Qualitäten. Die Lärmbelastung ist gering, die Parkplatzsituation durch zahlreiche Außenstellplätze entspannt. Das Image des Quartiers wird als solide, teils jedoch strukturell ausbaufähig beschrieben; die Nachfrage im Mietmarkt ist im Vergleich zu zentralen Ruhrgebietslagen schwächer, Neuvermietungen erfolgen langsamer. Einzelhändler, Ärzte und soziale Infrastruktur sind vor Ort, aber nur auf Basisniveau vorhanden.", "mietspiegel_eur_qm": "null", "mietspiegel_herkunft": "null", "berichts_abgleich": "null", "kaufpreisniveau": "Der Kaufpreis liegt mit 2.450.000 € exakt auf Höhe des hinterlegten Marktwerts, was einer Bewertung von ca. 1.445 €/m² Wohnfläche entspricht. Regional sind vergleichbare Objekte in der Größenordnung zwischen 1.250 und 1.500 €/m² zu finden, abhängig von Zustand und Lage. Das Preisniveau ist für die Lage (C-Lage, Randruhrgebiet) im oberen Bereich des Marktes und spiegelt derzeit nicht den baulichen Investitionsbedarf des Objekts wider. Der Bodenrichtwert von 90 €/m² unterstreicht das geringe Entwicklungspotenzial des Areals. Bei Berücksichtigung der nötigen Modernisierungskosten (mindestens 160.000 €) übersteigt die Gesamtinvestition das marktübliche Bewertungsband. Die Rohertragsfaktoren für Mehrfamilienhäuser mit ähnlich niedriger Rendite (3,5 %) liegen tendenziell niedriger, so dass der Objektpreis im oberen Marktband anzusetzen ist.", "lage_gegenueberstellung": [{"merkmal": "Makrolage", "objektfeld": "schwach", "bericht": null, "recherche": "Rückläufige Einwohnerzahl (-1,5 % in 10 Jahren), Arbeitslosenquote 9,5 %, unterdurchschnittliche Kaufkraft", "quelle": "https://www.it.nrw/statistik", "urteil": "stimmt", "kommentar": "Die Angaben des Investors decken sich mit amtlichen Daten – schwache Makrolage bleibt riskant."}, {"merkmal": "Mikrolage", "objektfeld": "durchschnittlich", "bericht": null, "recherche": "Einfache bis durchschnittliche Wohnlage, solide Infrastruktur, Nachfragesituation unter Marktniveau", "quelle": null, "urteil": "stimmt", "kommentar": "Die Mikrolage ist solide, aber ohne Nachfrageschub – Chancen auf Markterholung sind begrenzt."}, {"merkmal": "Bevoelkerungsentwicklung", "objektfeld": "stark_fallend", "bericht": null, "recherche": "Nachweislich rückläufige Bevölkerung in allen Altersklassen", "quelle": "https://www.it.nrw/statistik", "urteil": "stimmt", "kommentar": "Negativer Trend setzt sich statistisch fort, Aufwertung der Lage sehr unwahrscheinlich."}, {"merkmal": "Nachfrage", "objektfeld": "schwach", "bericht": null, "recherche": "Vermietungsdynamik gedämpft, Leerstände meist über dem Ruhrgebiets-Mittel", "quelle": null, "urteil": "stimmt", "kommentar": "Die nachfrageschwache Situation führt zu längeren Vermarktungszeiten und geringerer Mietdynamik."}, {"merkmal": "Wertsteigerung", "objektfeld": "niedrig", "bericht": null, "recherche": "Geringe Preissteigerungen, regionale Entwicklungsprognosen auf niedrigem Niveau", "quelle": null, "urteil": "stimmt", "kommentar": "Sowohl historische als auch prognostizierte Wertsteigerung bleibt gering."}, {"merkmal": "Entwicklung", "objektfeld": "kaum", "bericht": null, "recherche": "Lokale Infrastruktur und wirtschaftliche Entwicklung stagnieren, keine größeren Neubauprojekte", "quelle": null, "urteil": "stimmt", "kommentar": "Spielräume für Aufwertung oder Werthebel sind gering; keine sichtbaren Entwicklungsimpulse."}, {"merkmal": "Mietniveau", "objektfeld": null, "bericht": null, "recherche": "Mietniveau für Bestand ca. 5–6 €/m², bei Neubau selten über 8 €/m²", "quelle": "https://www.it.nrw/statistik", "urteil": "offen", "kommentar": "Das Mietniveau liegt nach Recherche unter dem für das Objekt kalkulierten Zielbild – Mieterhöhung ambitioniert."}, {"merkmal": "Kaufpreisniveau", "objektfeld": null, "bericht": null, "recherche": "Kaufpreisniveau für Bestand 1.250–1.500 €/m², hier 1.445 €/m²", "quelle": null, "urteil": "stimmt", "kommentar": "Preislich an der oberen Kante, wird durch den Erhaltungszustand nur zum Teil gerechtfertigt."}], "steuer_zusammenfassung": "Im ersten Jahr entstehen Werbungskosten von insgesamt 131.334 € (Schuldzinsen 84.526 €, AfA 40.500 €, steuerliche Bewirtschaftung 6.309 €), während die Mieteinnahmen bei 78.771 € liegen. Das Ergebnis aus Vermietung und Verpachtung beträgt damit -52.563 €, woraus sich im ersten Jahr eine Steuererstattung von 45.596 € ergibt (bei einem Grenzsteuersatz von 41,4 %). Eine positive Steuerwirkung (dauerhaft positiver Cashflow nach Steuer) tritt erst ab dem Jahr 2045 ein, da bis dahin die Abschreibung und vor allem die hohen Zinsaufwendungen die Einkunftsart dominieren. Nach Erreichen der positiven Schwelle (ab 2045) fällt faktisch keine Steuer mehr an, da das steuerliche Ergebnis erst ab dann einen Überschuss ausweist. Die kumulierte Steuerersparnis beträgt bis zur Wende -194.574 €. Im Sanierungsumfang (mind. 160.000 €) ist nicht explizit aufgeführt, ob sie sofort als Erhaltungsaufwand steuermindernd geltend gemacht wird – bei Instandsetzung bestehender Wohnungen würde das Ergebnis in den ersten Jahren weiter entlastet. Die AfA-Basis liegt bei 79,5 % des Kaufpreises, der AfA-Satz bei 2,0 % (50 Jahre Laufzeit aus Gebäudeanteil). Für die Steuerplanung sollte der Investor unbedingt Rücksprache mit seinem Steuerberater halten, um Sonderabschreibungen und Einmalaufwendungen korrekt einzuordnen.", "potenzial_text": "Ohne Mieterwechsel können gemäß aktuellem Plan kurzfristig Mieterhöhungen durchgesetzt werden, sobald bestehende Anpassungsfristen ablaufen. Das Zielbild sieht nach Umsetzung sämtlicher Sanierungen für acht Wohnungen ein jährliches Mietpotenzial von 96.180 € (Kaltmiete) vor, was im Ertragswert auf ca. 124.151 € Rohertrag/Jahr ansteigen könnte. Die Maßnahmen im Zielbild sind mit 160.000 € zu veranschlagen, sie steigern bei Erfolg den Ertragswert auf etwa 1.615.000 €, während der aktuelle Bestand auf 1.550.000 € taxiert ist. Die Mehrmiete oberhalb marktüblicher Werte wird im Ertragswert nicht angesetzt. Der Wertzuwachs aus dem Zielbild bleibt begrenzt, da auch die Marktdynamik schwach ist. Eine Wertaufteilung (WEG) ist bei diesem Objekt nicht möglich, das gesamte Potenzial liegt also auf Mieterhöhung und Substanzoptimierung.", "anschlussfinanzierung": "Am Ende der zehnjährigen Zinsbindung verbleibt eine Restschuld von rund 2.030.931 €. Der Objektwert dürfte sich bei moderater Wertsteigerung auf ca. 1.700.000 € bis 1.900.000 € (ertragswertbasiert) bewegen. Mit einem Anschlusszins von 5 % und weiterhin 1 % Tilgung steigt der Schuldendienst und der DSCR verbessert sich nur schwach, so dass ohne zusätzlichen Eigenkapitaleinsatz (empfohlen: mindestens 100.000–200.000 € als Sondertilgung) oder signifikante Mietsteigerungen der negative Cashflow andauert. Die Anschlussfinanzierung ist vor allem bei Marktabschwächung oder steigendem Leerstand kritisch. Langfristig trägt sich das Investment nur, wenn Substanzrisiken durch Sanierungen beseitigt werden und die Einnahmen steigen.", "score_vergleich": "Der DealPilot-Score (15/100) fällt noch niedriger aus als der Investor Deal Score (38/100), da Erstgenannter ausschließlich finanzielle Kennzahlen wie Cashflow und Schuldendienstdeckung gewichtet. Der (schwache) Investor Deal Score spiegelt zusätzlich die schlechte Lage, den baulichen Zustand, das schwache Wertsteigerungspotenzial und die Demografie wider, sodass selbst bei Potenzialbewertung kaum Spielraum nach oben bleibt. Die starke Divergenz ist Ausdruck der Marktschwäche im Zusammenspiel mit niedriger Mietrendite und erhöhtem Finanzierungsrisiko.", "optischer_eindruck": "Das Foto zeigt einen siebengeschossigen, typischen Klinkerbau der Nachkriegsmoderne ohne auffällige Fassadendetails. Die Fassade ist schlicht und wirkt optisch gepflegt, wenngleich modernisierungsbedürftig. Fenster und Hauseingang wirken etwas älter, das Gebäudeumfeld ist ordentlich gestaltet und durch große Hecken eingefasst. Die Umgebung erinnert an eine ruhige Siedlung mit grundlegender, aber nicht herausragender Infrastruktur. Der Gesamteindruck entspricht dem Bild eines in die Jahre gekommenen Mietshauses einfacher bis durchschnittlicher Kategorie. Bild und hinterlegter Zustand 'renovierungsbedürftig' stimmen überein.", "quellen": ["https://www.it.nrw/statistik"], "_fuer": {"kuerzel": "DEMO-HH1", "adresse": "Lindenhof 14, 44577 Castrop-Rauxel", "stand": "2026-11-09T14:07:39.082Z", "abdruck": {"kp": "2450000", "nkm": "7071", "wfl": "1696", "baujahr": "1972", "objart": "MFH", "zimmer": "64", "d1z": "4,0", "d1t": "1,0", "ek": "472365", "gsfl": "2100", "brw": "90", "mea": "100", "ds2_zustand": "renovierungsbeduerftig", "ds2_energie": "G", "makrolage": "schwach", "mikrolage": "durchschnittlich", "lageklasse": "C", "hg_nul": "7680", "leerstand": "0", "einheiten": "24"}}}};
